(window.MUSEUM_MATCH_T = window.MUSEUM_MATCH_T || {})["ar"] = {"ui":{"lead":"مباريات عظيمة، نقلةً بعد نقلة. تابع على الرقعة مباريات مشهورة بينما يشرح Musowl كل نقلة.","all":"الكل","k_chess":"الشطرنج","k_shogi":"الشوغي","k_go":"الغو","k_xiangqi":"شيانغتشي","side_r":"الأحمر","res_r":"فوز الأحمر","back":"العودة إلى المباريات العظيمة","start":"البداية","prev":"نقلة إلى الوراء","next":"نقلة إلى الأمام","end":"النهاية","play":"تشغيل تلقائي","pause":"إيقاف","moves":"النقلات","move":"النقلة {n}","startpos":"وضع البداية","nextnote":"الشرح التالي (النقلة {n})","quiet":"لا يوجد شرح لهذه النقلة.","guide":"Musowl","keys":"← → للتنقل نقلةً نقلة","result":"النتيجة","r_event":"المباراة","r_date":"السنة","r_place":"المكان","side_w":"الأبيض","side_b":"الأسود","side_s":"سينتي","side_g":"غوتي","side_B":"الأسود","side_W":"الأبيض","res_w":"فوز الأبيض","res_b":"فوز الأسود","res_d":"تعادل","res_s":"فوز سينتي","res_g":"فوز غوتي","credit":"النقلات هي السجل المعروف لكل مباراة. الشروح من كتابة Musowl في المتحف.","caps":"المأسورة","hand":"في اليد","pnote":"الشرح السابق","nnote":"الشرح التالي","plies":"{n} نقلة","about":"عن هذه المباراة"},"opera":{"t":"مباراة الأوبرا","w":"بول مورفي","b":"دوق برونزفيك كارل الثاني والكونت إيزوار","ev":"لُعبت في مقصورة بدار أوبرا باريس (الحليفان يتشاوران معًا)","d":"1858","pl":"فرنسا (باريس)","lead":"البطل الأمريكي الشاب في مواجهة نبيلَين، أثناء عرض في الأوبرا: سبع عشرة نقلة. أخرِج القطع بسرعة، وضحِّ بها دون تردد، وأنهِ المباراة بقطع قليلة جدًا. لا توجد مباراة تظهر في كتب الشطرنج أكثر منها.","c":{"0":"باريس، 1858. كان الأمريكي بول مورفي، ابن الحادية والعشرين، يهزم أقوى لاعبي أوروبا واحدًا تلو الآخر. في تلك الليلة، في مقصورة بدار الأوبرا، أخذ دوق برونزويك والكونت إيزوار القطع السوداء معًا وتحدّياه، يتشاوران في كل نقلة. ويُقال إن مورفي أراد أن ينهي المباراة بسرعة ليشاهد العرض. هذه النقلات السبع عشرة مليئة بالأساسيات: أخرِج القطع بسرعة وضع الملك في أمان.","1":"يتقدّم الأبيض ببيدق الملك مربعين. ينظر إلى d5 وe5 في الوسط ويفتح الطريق للفيل والوزير.","2":"يلعب الأسود e5 أيضًا. يتواجه البيدقان في الوسط، ولا يستطيع البيدق الأبيض التقدّم أكثر.","3":"يخرج الحصان إلى f3 ويهاجم بيدق e5. نقلة جيدة: تطوّر قطعة وتجعل الخصم يفكّر في الدفاع.","4":"يحمي الأسود e5 بـ d6. يُسمّى هذا دفاع فيليدور. إنه متين، لكنه يضيّق قليلًا طريق فيل f8.","5":"يلعب الأبيض d4: بيدق آخر إلى الوسط في مواجهة e5. على الأسود أن يختار بين الأخذ والحماية.","6":"الفيل الأسود إلى g4. يضغط على حصان f3 الواقع على خط واحد مع الوزير الأبيض في d1. إذا تحرّك الحصان ضاع الوزير، فلا يستطيع الحصان الذهاب إلى e5.","7":"يأخذ الأبيض في e5 بالبيدق. لو استردّ الأسود فورًا ببيدق d6 لبادل الأبيض الوزيرين ثم أخذ الحصان بيدق e5. لذلك يريد الأسود أولًا التخلّص من حصان f3.","8":"يأخذ الأسود الحصان بالفيل. صار بإمكانه الآن استرداد e5 بأمان. لكن مبادلة الفيل الذي خرج للتو بالحصان تجعل الأسود متأخرًا في التطوير.","9":"يستردّ الأبيض بالوزير الذي يعمل بالفعل قرب الوسط، بينما لم يُخرج الأسود تقريبًا أي قطعة.","10":"يستردّ الأسود ببيدق والعتاد متعادل. لكن الأبيض متقدّم في عدد القطع المطوَّرة.","11":"الفيل إلى c4. مع وزير f3 يصوّب نحو f7. لا يحمي f7 إلا الملك، فهو مربع ضعيف: أخذه يعني كش مات.","12":"يضع الأسود الحصان في f6 ويسدّ العمود f. لولا ذلك لأخذ الوزير f7 بكش مات. الدفاع مع التطوير هو الردّ الصحيح.","13":"ينعطف الوزير إلى b3 ويهاجم f7 وb7 معًا. النقلة ذات التهديدين قوية لأن الخصم لا يستطيع صدّهما معًا.","14":"يضع الأسود الوزير في e7 ليحمي f7 ويترك b7. لكن الوزير الآن يسدّ طريق فيل f8.","15":"لا يأخذ مورفي بيدق b7، بل يُخرج حصانًا. لو أخذه لابتعد الوزير كثيرًا. تفضيل التطوير السريع على بيدق هو أسلوب مورفي تمامًا.","16":"يلعب الأسود c6: يسيطر على d5 وb5 ويفتح طريقًا للوزير نحو b6.","17":"الفيل إلى g5 يثبّت حصان f6. إذا تحرّك الحصان يمكن أخذ الوزير في e7 خلفه. صار تحريك قطع الأسود أصعب فأصعب.","18":"يلعب الأسود b5 ليطرد فيل c4. يكسب مساحة في جناح الوزير، لكنه يفتح ثغرة لدخول قطع الأبيض.","19":"يُضحّى بالحصان ليأخذ في b5! بدل سحب الفيل، يواصل مورفي الهجوم. والملك الأسود ما زال في الوسط، وهذا خطير جدًا على الأسود.","20":"يأخذ الأسود الحصان ويتقدّم بحصان. لكن ملكه ما زال في e8، وقطع الأبيض تواصل التجمّع.","21":"الفيل إلى b5، كش! الملك الأسود ما زال عالقًا في الوسط. للأبيض بيدقان مقابل الحصان، ويتّجه مباشرة نحو الملك.","22":"يسدّ الأسود بالحصان في d7. لكن هذا الحصان مثبّت: إذا تحرّك صار الملك الأسود في كش. الآن سيصوّب الأبيض نحو d7.","23":"يبيّت الأبيض في جهة الوزير. صار الملك آمنًا، وفي الوقت نفسه وصل الرخ إلى d1 ليصوّب نحو d7. نقلة واحدة تدافع وتهاجم: رائعة.","24":"يضع الأسود الرخ في d8 ليحمي d7. ما زال لا يستطيع التبييت، والرخ في h8 والفيل في f8 لا يفعلان شيئًا.","25":"يُضحّى بالرخ ليأخذ في d7! يعطي الأبيض رخًا ليزيل أحد مدافعي الأسود.","26":"يستردّ الأسود بالرخ. الآن هذا الرخ في d7 مثبّت أيضًا: إذا تحرّك أعطى فيل b5 كشًّا للملك الأسود.","27":"يصل الرخ الآخر إلى d1 ويهاجم d7 من جديد. صار عدد القطع البيضاء المهاجِمة لـ d7 أكثر من القطع السوداء المدافِعة.","28":"الوزير الأسود إلى e6، يعرض مبادلة الوزيرين ليُبعد وزير b3 ويريد مساعدة d7. لكن الأوان قد فات.","29":"يأخذ الفيل في d7 مع كش. يزيل الأبيض مدافعي الأسود واحدًا تلو الآخر.","30":"يستردّ الأسود بالحصان. بعد مغادرة الحصان f6 انفتح القطر من فيل g5 إلى d8. وسيكون لهذا القطر دور في النهاية.","31":"يُضحّى بالوزير في b8 مع كش! إنها أشهر نقلة في المباراة. لا بد أن يأخذ الأسود بالحصان، وعندما يغادر الحصان d7 ينفتح العمود d.","32":"يأخذ الأسود بالحصان. الآن لا توجد قطعة سوداء تحمي d8.","33":"الرخ إلى d8، كش مات! فيل g5 يدعم d8، والملك الأسود محاصر بقطعه نفسها فلا مهرب. أعطى الأبيض الوزير والرخ والفيل وأنهى برخ وفيل فقط. طوِّر بسرعة، أمِّن ملكك، وهاجم ما دام ملك الخصم في الوسط: تجمع هذه المباراة الشهيرة كل هذه الأفكار المهمة."}},"reti1910":{"t":"كش مات ريتي","w":"ريتشارد ريتي","b":"سافيلي تارتاكوفر","ev":"مباراة ودية (ليست في بطولة)","d":"1910","pl":"النمسا (فيينا)","lead":"لاعبان سيصبحان من كبار الأساتذة، في مباراة ودية في فيينا، إحدى عشرة نقلة. يضحّي الأبيض بالوزير وينهي المباراة بكش مزدوج: قطعتان تكشّان في الوقت نفسه. ويُسمّى هذا الشكل من الكش مات باسم الأبيض: كش مات ريتي.","c":{"0":"فيينا، 1910. الأبيض ريتشارد ريتي ابن العشرين، والأسود سافيلي تارتاكوفر. أصبح كلاهما من أفضل لاعبي العالم، ويُعرفان بإدخال أفكار جديدة إلى الشطرنج. لم تكن مباراة في بطولة، بل مباراة ودية على رهان صغير. إنها قصيرة، لكنها تُظهر بوضوح لماذا يجب تأمين الملك مبكرًا.","1":"يتقدّم الأبيض ببيدق الملك مربعين. السيطرة على الوسط تسهّل خروج القطع الخلفية. وانفتح الطريق للفيل والوزير.","2":"يلعب الأسود c6. بدل الذهاب إلى الوسط فورًا، يستعد لـ d5 لمهاجمة بيدق e4. يُسمّى هذا الافتتاح المتين دفاع كارو-كان.","3":"يضع الأبيض البيدق الآخر في d4 أيضًا. بيدقان متجاوران في الوسط: للأبيض مساحة كبيرة. سيحاول الأسود تفكيكهما.","4":"كما خُطّط، d5. البيدق يتحدّى e4: \"أستطيع أخذك\". على الأبيض أن يقرّر: الحماية أو التقدّم أو المبادلة.","5":"يُخرج الأبيض حصانًا ليحمي e4. يطوّر قطعة ويدافع في الوقت نفسه دون إضاعة وقت.","6":"يأخذ الأسود بيدق e4. بمبادلة بيادق الوسط يصغر وسط الأبيض.","7":"يستردّ الأبيض بالحصان، فيقف في وسط الرقعة. الحصان في الوسط يصل إلى مربعات كثيرة وهو قوي جدًا.","8":"يُخرج الأسود حصانًا في مواجهة حصان e4. يُلعب هنا غالبًا الفيل إلى f5، لكن الأسود يدعو إلى مبادلة الحصانين.","9":"يخرج الوزير مبكرًا إلى d3 ليحمي حصان e4. عادةً لا يُخرَج الوزير بهذه السرعة، لكن للأبيض خطة. تذكّر أن هذا الوزير يقف على العمود d أمام الملك الأسود.","10":"يلعب الأسود e5 ويعرض بيدقًا ليفتح الطريق للفيل والوزير. نقلة نشطة تُشعل القتال في الوسط.","11":"يأخذ الأبيض بيدق e5. قبل الهدية، لكن الوزير الأسود صار أكثر حرية.","12":"كش! الوزير الأسود في a5 يصوّب قطريًا نحو الملك في e1. وفي الوقت نفسه يريد استرداد بيدق e5: مهمتان في نقلة واحدة. على الأبيض أن يسدّ.","13":"يسدّ الأبيض الكش بالفيل في d2. يمكن للوزير أخذ الفيل، لكن الوزير الأبيض يحميه جيدًا.","14":"استردّ الأسود البيدق وعاد التعادل في العتاد. وهذا الوزير ينظر على العمود e إلى حصان e4 والملك خلفه. إذا تحرّك الحصان صار الملك في كش، فالحصان مقيّد. يبدو أن الأسود سيربحه قريبًا.","15":"يبيّت الأبيض في جهة الوزير. يغادر الملك العمود e فيتحرّر الحصان. وفي الوقت نفسه يصل رخ إلى d1: الرخ في d1 والوزير في d3 والمربع d8 بجانب الملك الأسود صارت على خط واحد. هذا هو فخّ الأبيض.","16":"يأخذ الأسود حصان e4 ويبدو أنه ربح قطعة. لكن الملك الأسود ما زال في e8 ولم يبيّت. قطع الأبيض مصطفّة على العمود d، والملك الأسود بلا حماية. هذه النقلة الخاسرة هي نقطة التحوّل.","17":"الوزير إلى d8، كش! يقدّم الأبيض أقوى قطعه مجانًا. القطعة السوداء الوحيدة التي تستطيع أخذه هي الملك. بتركه يُؤخذ، يجرّ الأبيض الملك إلى المربع الخطِر d8.","18":"لا بد أن يأخذ الأسود بالملك؛ لا طريقة أخرى لصدّ الكش. صار الملك في d8، ورخ d1 ينتظر خلفه.","19":"يتحرّك الفيل من d2 إلى g5 بكش، وفي الوقت نفسه يفتح الطريق لرخ d1 الذي يكشّ أيضًا على العمود d. قطعتان تكشّان معًا: كش مزدوج. لا يمكن صدّه بأخذ قطعة ولا بالسدّ، فعلى الملك أن يهرب.","20":"يهرب الملك إلى c7. لو ذهب إلى e8 لجاء الرخ إلى d8 وأعطى كش مات. أينما ذهب الملك، فالضربة الأخيرة جاهزة لدى الأبيض.","21":"الفيل إلى d8: كش مات على القطر للملك في c7! الفيل يحميه رخ d1، فلا يستطيع الملك أخذه. مربعات مثل b8 وc8 وb7 وc6 مشغولة بقطع الأسود نفسه، والرخ يراقب d6 وd7. في إحدى عشرة نقلة فقط ضحّى الأبيض بالوزير وفاز بقطعتين صغيرتين. تعلّمنا هذه المباراة مدى خطورة السعي وراء العتاد قبل التبييت. وتقول بعض السجلات إن الأسود استسلم قبل ذلك بنقلة."}},"immortal":{"t":"المباراة الخالدة","w":"أدولف أندرسن","b":"ليونيل كيزيريتسكي","ev":"مباراة غير رسمية في استراحة بطولة لندن 1851","d":"1851","pl":"المملكة المتحدة (لندن)","lead":"لندن، أثناء أول بطولة شطرنج دولية: مباراة لُعبت في استراحة. يضحّي الأبيض بفيل ورخّين ثم بالوزير، ويعطي كش مات بالقطع الصغيرة الثلاث الباقية. ويُقال إن الأسود استسلم قبل النهاية، وإن النقلات الأخيرة هي الختام الذي عرضه الأبيض.","c":{"0":"لندن، يونيو 1851. في تلك السنة كانت أول بطولة دولية للشطرنج في العالم تُقام في لندن. يلعب بالأبيض أدولف أندرسن، معلّم الرياضيات الألماني، وبالأسود ليونيل كيزيريتسكي الذي كان يعلّم الشطرنج في مقهى «لا ريجانس» في باريس. لم تكن هذه مباراة من البطولة، بل مباراة ودية لُعبت في استراحة. نشر كيزيريتسكي النقلات في مجلته الخاصة فانتشرت، وصارت هذه المباراة تُسمّى لاحقًا «المباراة الخالدة». لنشاهد معركة تمثّل عصرها، مليئة بالقطع التي تُرمى في الهجوم. يرافقك Musowl.","1":"يدفع الأبيض البيدق الذي أمام الملك مربعين. صار يراقب مربعَي الوسط d5 وf5، وانفتحت الطرق للفيل والوزير. قديمًا وحديثًا، هذه هي النقلة الأولى الأكثر شيوعًا.","2":"يلعب الأسود أيضًا e5. تتواجه البيادق وجهًا لوجه ولا يتخلّى الأسود عن الوسط. وانفتحت كذلك طرق الفيل والوزير الأسودين.","3":"f4! يقدّم الأبيض بيدقًا مجانًا: هذا هو «جامبيت الملك». إذا أخذه الأسود يغادر بيدقه في e5 الوسط، ويسهل على الأبيض أن يدفع بيدقًا إلى d4 أيضًا. في ذلك العصر كانت هذه الخطط التي تبدأ الهجوم مبكرًا محبوبة جدًا. لكن نقطة ضعفها أن المساحة أمام الملك الأبيض تنفتح.","4":"يقبل الأسود البيدق. البيدق في f4 يسدّ طريق الفيل الأبيض في c1، ويراقب أيضًا المربعين e3 وg3. صار للأسود بيدق زائد.","5":"يُخرج الأبيض الفيل إلى c4. المربع f7 بجوار الملك الأسود ضعيف لأن الملك وحده يحميه. يصوّب الأبيض نحوه ليستطيع الهجوم في أي لحظة.","6":"كش! لأن الأبيض دفع بيدق العمود f، كان القطر من h4 إلى e1 مفتوحًا. إذا اعترض الأبيض بـ g3 فسيأكله بيدق f4 ببساطة. على الأبيض أن يحرّك الملك.","7":"يتنحّى الملك إلى f1. الآن لم يعد الأبيض قادرًا على التبييت ولا على إخفاء ملكه في مكان آمن. في المقابل، خرج الوزير الأسود مبكرًا جدًا، فيستطيع الأبيض مطاردته وهو يُخرج قطعه.","8":"يقدّم الأسود هو أيضًا بيدقًا مجانًا. بـ b5 يستدرج فيل c4 ويبعده عن القطر الذي يصوّب نحو f7. سُمّيت هذه النقلة لاحقًا «جامبيت برايان المضاد»، وكانت نقلة هجومية يحب كيزيريتسكي استعمالها.","9":"يأخذ الأبيض البيدق. غادر الفيل c4 فلم يعد يصوّب نحو f7. لكن الأبيض استعاد بيدقًا وعاد العدد متساويًا.","10":"يذهب الحصان الأسود إلى f6. يهاجم بيدق e4 ويساعد أيضًا في حماية الملك: مربع جيد. بدأ سباق إخراج القطع.","11":"يخرج الحصان الأبيض أيضًا إلى f3. يُخرج قطعة ويهدّد الوزير في h4 في الوقت نفسه: نقلة ممتعة جدًا. على الوزير أن يهرب، فيكسب الأبيض نقلة.","12":"يتراجع الوزير إلى h6. من هنا يراقب العمود h ويرى الرخ في h1 خلف بيدق الأبيض في h2. ما زال مربعًا آمنًا.","13":"بـ d3 يحمي الأبيض بقوة بيدق e4 الذي كان مهدَّدًا. وفي الوقت نفسه ينفتح طريق فيل c1. نقلة هادئة لا تُضيّع شيئًا.","14":"يذهب الحصان الأسود إلى h5. يحمي بيدق f4 ويخطّط للقفز إلى g3. القفز إلى g3 سيعطي كشًّا ويهاجم رخ h1؛ وإذا أخذه الأبيض ببيدق h2 ينفتح العمود h ويستطيع وزير h6 أخذ رخ h1. خطة حادّة إلى حدّ ما.","15":"يذهب الحصان الأبيض إلى h4. هذا الحصان يسدّ العمود h، فحتى لو قفز الحصان الأسود إلى g3 لم يعد رخ h1 قابلًا للأخذ. كما أنه يستعدّ للقفز إلى f5 لتهديد الوزير في h6.","16":"يذهب الوزير الأسود إلى g5 ويهاجم الحصان في h4. على الأبيض أن يقرّر: هل يحميه أم ينقله إلى مكان آخر؟","17":"يقفز الحصان إلى f5. وهو محميّ ببيدق e4، فهذا موقع قويّ جدًا. من هنا يهاجم بيدق g7 ويراقب المربعين h6 وd6. قطع الأبيض تقترب من الملك الأسود.","18":"بـ c6 يحاول الأسود طرد الفيل من b5. إذا هرب الفيل يستطيع الأسود توسيع الوسط ببيادقه. نقلة عادية ومعقولة.","19":"لكن الأبيض لا ينقذ الفيل ويلعب g4! مهدّدًا الحصان في h5. الأبيض مستعدّ لخسارة فيل كي يطارد قطع الأسود ويكسب وقتًا للهجوم: فكرة جريئة. بيدق g4 يحميه وزير d1 قطريًا.","20":"الحصان المهاجَم في h5 يعود إلى f6. يقرّر الأسود أن أخذ الفيل الأبيض يمكن أن ينتظر. بيدق c6 ما زال يهاجم الفيل في b5.","21":"يذهب الرخ إلى g1. يحمي بيدق g4 ويستعدّ للقتال على العمود g. ما زال فيل b5 متروكًا ليؤخذ. يرى الأبيض أن مطاردة الوزير الأسود أهمّ من فيل واحد.","22":"يأخذ الأسود الفيل. في العتاد صار الأسود متقدّمًا بفيل كامل، وهي أفضلية كبيرة. لكن ما عدا الوزير وحصانًا واحدًا، ما زالت قطع الأسود في مربعات البداية. من هنا يبدأ هجوم الأبيض.","23":"h4! يطارد الأبيض بالبيدق الوزير الأسود في g5. بمجرد دفع البيادق، يقلّص الأبيض باستمرار الأماكن التي يمكن للوزير الأسود الوقوف فيها.","24":"يهرب الوزير إلى g6. ما زالت لديه بعض المربعات، لكنه بدأ يُحاصَر ببيادق الأبيض وحصانه.","25":"بـ h5 يطارد الأبيض الوزير مرة أخرى. كلما تقدّم بيدق أبيض، لا يستطيع الوزير الأسود إلا التراجع.","26":"يعود الوزير إلى g5. حصان f5 يراقب h6 والمربعات الأخرى مسدودة، فلم يبقَ له تقريبًا مكان غير هذا. الوزير الأسود يُحشر في الزاوية شيئًا فشيئًا.","27":"يذهب الوزير الأبيض إلى f3. إذا أخذ فيل c1 الآن بيدق f4، سيصبح وزير g5 مهاجَمًا ولن يجد تقريبًا مربعًا للهرب. إنها نقلة تنصب فخًّا للإمساك بالوزير.","28":"يعيد الأسود الحصان إلى g8 ليُخلي للوزير مربع الهرب f6. عودة حصان خرج من قبل إلى مربع بدايته علامة على أن الأسود في ورطة. في سباق إخراج القطع، الأبيض متقدّم كثيرًا.","29":"يأخذ الفيل بيدق f4، فيستعيد بيدقًا وهو يطارد الوزير في g5. وأخيرًا ينضمّ الفيل الأبيض أيضًا إلى المعركة.","30":"يهرب الوزير إلى المربع الذي أعدّه، f6. من هنا يرى قطريًا حتى بيدق b2، ويمكنه أيضًا التصويب نحو رخ a1 خلفه.","31":"يذهب الحصان الأبيض إلى c3. حصان c3 يسدّ أيضًا القطر من وزير f6 إلى b2. وبعد ذلك يخطّط للقفز إلى d5 لتهديد الوزير في f6.","32":"يُخرج الأسود الفيل إلى c5 ويهاجم رخ g1. أخيرًا يُخرج الأسود فيلًا وينضمّ إلى الهجوم. هل يذهب لجمع القطع أم يدافع عن الملك؟ كانت لحظة مهمة للأسود.","33":"الحصان إلى d5! يهدّد وزير f6، وهناك أيضًا قفزة إلى c7 تهاجم الملك والرخ معًا. لكن لأن الحصان غادر c3، انفتح من جديد طريق الوزير الأسود إلى b2. لا يحاول الأبيض حماية رخ g1 ولا بيدق b2. إنه مستعدّ لترك قطعه تؤخذ كي يهاجم الملك الأسود.","34":"يأخذ الوزير الأسود بيدق b2 ويصوّب الآن نحو رخ a1. الفكرة هي جمع قطع كثيرة والفوز بالعدد. لكن الوزير يبتعد أكثر فأكثر عن ملكه.","35":"الفيل إلى d6! الآن يترك الأبيض الرخّين كليهما ليؤخذا. في المقابل يسيطر الفيل على f8 وe7 ويسدّ طرق هرب الملك الأسود. لم يختر الأبيض عدّ القطع، بل نسج شبكة للإمساك بالملك الأسود. هذه هي نقطة التحوّل في المباراة.","36":"يأخذ الأسود رخ g1. صار للأسود فيل ورخ زائدان. لكن دراسات لاحقة تقول إن نقلة أخرى كانت أفضل هنا، وإن الأسود كان يملك دفاعًا أقوى.","37":"e5! نقلة بيدق هادئة، لكنها من الضربات الحاسمة. هذا البيدق يسدّ قطر الوزير من b2 إلى g7 ويسيطر أيضًا على f6. لم يعد الوزير الأسود قادرًا على العودة لمساعدة ملكه، ولا يستطيع حصان g8 الخروج إلى f6. يهدّد الأبيض الآن بأخذ g7 بالحصان مع كش، ثم الكش مات بالفيل في c7.","38":"يأخذ الأسود الرخ الآخر أيضًا مع كش. كان الصف الأول كله من a1 إلى f1 مفتوحًا. أخذ الأسود الرخّين ويتقدّم كثيرًا في العتاد.","39":"يتنحّى الملك إلى e2. لم يبقَ للأبيض من القطع الكبيرة إلا الوزير، ومعه حصانان وفيل. ومع ذلك، حول الملك الأسود للأبيض قطع أكثر بكثير من الأسود.","40":"يُخرج الأسود الحصان إلى a6 ليحمي c7. الغرض منع الكش مات الذي يأخذ فيه الحصان g7 مع كش، ويهرب الملك إلى d8، ثم يُنهي الفيل في c7. ويقال إن كيزيريتسكي استسلم تقريبًا هنا، وإن بقية النقلات عرضها الأبيض.","41":"الحصان يأخذ بيدق g7 مع كش! حصان g7 يهاجم الملك في e8. فيل d6 يسيطر على e7 وf8، لذلك لا يجد الملك أماكن كثيرة يذهب إليها.","42":"على الملك أن يهرب إلى d8. لا يستطيع البقاء في e8 ولا الذهاب إلى e7 أو f8؛ كان d8 المربع الوحيد الباقي.","43":"يضحّي الأبيض بالوزير في f6 مع كش! حتى آخر قطعة كبيرة تُعطى مجانًا. يعطي الوزير كشًّا قطريًا من f6 مرورًا بـ e7 إلى d8، ولا خيار للأسود إلا أخذه.","44":"يأخذ الأسود الوزير بحصان g8. لا مكان للملك ليهرب إليه، فلا توجد نقلة أخرى. لكن ابتعاد هذا الحصان بالذات هو ما يُكمل شبكة الكش مات.","45":"يذهب الفيل إلى e7. كش مات! حصان d5 يسيطر على e7 وc7، وحصان g7 يسيطر على e8، وقطع الأسود نفسها تسدّ c8 وd7. أعطى الأبيض فيلًا ورخّين وحتى الوزير، وفاز بثلاث قطع صغيرة فقط. ما زال لدى الأسود وزير ورخّان، لكن لا شيء منها يصل في الوقت المناسب. تعلّمنا هذه المباراة أن مدى عمل قطعك أهمّ من عددها، وهي من أشهر المباريات في تاريخ الشطرنج. ويقال إن اسمها أطلقه بعد بضع سنوات الأستاذ النمساوي فالكبير."}},"mimiaka":{"t":"مباراة الأذنين المحمرّتين","w":"هونينبو شوساكو","b":"إينوي غينان إنسيكي","ev":"مباراة في أوساكا (على ثلاثة أيام)","d":"1846","pl":"اليابان (أوساكا)","lead":"واجه شوساكو، وهو في السابعة عشرة (4 دان)، غينان (8 دان)، أحد أقوى لاعبي عصره. يُروى أن أذني غينان احمرّتا عند النقلة 127، ومن هنا جاء الاسم. لم يكن هناك كومي آنذاك: فاز الأسود بنقطتين.","c":{"0":"أوساكا، 1846. الأسود: شوساكو، 17 عامًا، 4 دان. الأبيض: إينوي غينان إنسيكي، 8 دان، نحو 48 عامًا، من أقوى لاعبي عصره، وقد نافس هونينبو جووا على منصب ميجين غودوكورو. في اليوم السابق بدأ شوساكو بحجرين مسبقين كما يقتضي فارق الدرجة، لكن غينان أدرك قوته سريعًا فأوقف تلك المباراة، ولعب شوساكو هذه بالأسود مباشرة. لم يكن هناك كومي، فلا يُحسب إلا ما على اللوحة من أرض. لنتابع هذه المباراة ذات الأيام الثلاثة نقلةً نقلة.","1":"الأسود 1 على نقطة 3-4 في الأعلى يمينًا (R16). توازن بين أرض الزاوية وإمكان الامتداد على الجانبين. كان شوساكو يحب نقاط 3-4 حين يلعب بالأسود.","2":"الأبيض 2 على نقطة 3-4 في الأعلى يسارًا (D17). في الافتتاح تأتي الزوايا أولًا لأن الأرض تُصنع فيها بأسهل طريقة. يتقاسم الطرفان الزوايا الفارغة.","3":"الأسود 3 على نقطة 3-4 في الأسفل يمينًا (Q3). يتناسق مع R16 بحيث يصبح الجانب الأيمن بين الزاويتين لاحقًا منطقة سوداء كبيرة.","4":"الأبيض 4 (P17) يقترب من زاوية الأسود العليا اليمنى. لو لعب الأسود هناك مرة أخرى لصارت الزاوية متينة جدًا، لذا يتحرك الأبيض أولًا. يستطيع الأسود أن يرد أو أن يأخذ نقطة كبيرة أخرى.","5":"الأسود 5 لا يرد بل يأخذ نقطة 3-4 في الأسفل يسارًا (C4). ثلاث نقاط 3-4 في النقلات 1 و3 و5 نمط يتكرر كثيرًا في مباريات شوساكو بالأسود. التعامل مع P17 يمكن أن ينتظر.","6":"الأبيض 6 (C14) على الجانب الأيسر. المعتاد الاقتراب من الزاوية السفلى اليسرى، لكن غينان يبني على الجانب مع D17. نقلة غير مألوفة قليلًا تمنع مسبقًا C4 من التمدد صعودًا.","7":"الأسود 7 (E4) يغلق الزاوية السفلى اليسرى بحجر ثانٍ، فتصبح شبه مضمونة للأسود. وبالدفاع قبل اقتراب الأبيض يحدّ أيضًا من فعالية الأبيض 6 على اليسار.","8":"الأبيض 8 (R5) يقترب من Q3. مع نقطتي 3-4 سوداوين في طرفي الجانب الأيمن، يحتاج الأبيض موطئ قدم هناك. تبدأ معركة طويلة في الأسفل يمينًا.","9":"الأسود 9 (Q15) يدافع في الأعلى يمينًا. وُضع تحت P17 فيقوّي الزاوية ويدفع P17 نحو الحافة العليا الضيقة. يريد الأسود أن يبقى الجانب الأيمن من نصيبه.","10":"الأبيض 10 (O4) هو «التايشا»: يغطي أحجار الأسود قطريًا من مسافة قصيرة. تفرعاته كثيرة حتى إن مثلًا قديمًا يتحدث عن «وجوه التايشا المئة»، وكان اختصاص غينان. كيف سيواجه شوساكو ابن السابعة عشرة سلاح خصمه المفضل؟","11":"بالنقلة 11 (Q5) يلتصق الأسود بـR5 ويقبل القتال. كان الدفاع الهادئ ممكنًا، لكن شوساكو يختار المسار الكثير التفرعات. تبدأ مبارزة في الحساب.","12":"الأبيض 12 (Q4) يقتحم بين أحجار الأسود ليفصل Q3 عن Q5 ويُضعف أحدهما.","15":"بالنقلتين 13 (P4) و15 (P3) يصل الأسود أحجاره السفلية بإحكام. دخل الأبيض 14 (R4) الزاوية فصارت متنازعًا عليها. يفضّل الأسود البقاء متصلًا وقويًا ولو تنازل عن شيء من الزاوية.","17":"مع الأبيض 16 (P5) والأسود 17 (Q6) تنمو الأحجار صعودًا. يُطل الأسود برأسه نحو الجانب الأيمن، ويضغط الأبيض من الأعلى ليحبسه.","19":"الأبيض 18 (R3) يضيف حجرًا في الزاوية ليعيش، والأسود 19 (O3) يكبح الأبيض في الجانب السفلي. خطة الأسود: ترك الزاوية مقابل القوة في الخارج أسفلًا ويمينًا.","20":"الأبيض 20 (P6) يغطي Q6 من الأعلى محاولًا حبس الأسود منخفضًا على اليمين. إن لم يخرج الأسود صعودًا فستعيش أحجاره اليمنى بالكاد دون مكسب يُذكر.","21":"بالنقلتين 21 (Q7) و23 (Q8) يزحف الأسود صعودًا على الجانب الأيمن بحثًا عن مخرج، بينما يضغط الأبيض 22 (P7) بجانبه. السلسلة السوداء الطويلة على الخط الثالث منخفضة وأرضها قليلة، لكنها حية بوضوح.","24":"الأبيض 24 (N4) يغلق من الخارج حجري الأسود O3–P3 في الأسفل. صارت أحجار الأسود تتجه اتجاهين، يمينًا وأسفل، وحماية الاثنين معًا تزداد صعوبة.","25":"الأسود 25 (N3) يمتد خطوة في الأسفل. تقول الدراسات اللاحقة إن نقلة أخرى تعتمد على «السلّم» كانت أفضل، لذا تُعدّ هذه هفوة الأسود الصغيرة في المباراة. تبقى أحجار الأسود السفلية منخفضة وسهلة التطويق، فتمنح الأبيض فرصة للهجوم المضاد. حتى شوساكو قد يضلّ داخل الشكل المفضل لخصمه.","26":"الأبيض 26 (P8) يغطي أحجار الأسود اليمنى من الأعلى. لا يستطيع الأسود الخروج صعودًا، وهو مهدد بالحبس في الأسفل أيضًا.","28":"الأبيض 28 (M3) يلتصق مباشرة بـN3: نقلة قاسية. توقف تمدد الأسود في الأسفل وتسلبه مساحة الحياة، وتجبره على إضافة أحجار. عاقب غينان هفوة النقلة 25 فورًا.","30":"بعد الأسود 29 (M2) يلتف الأبيض 30 (L2) من الأسفل أيضًا. لا تستطيع أحجار الأسود السفلية الخروج لا نحو الخارج ولا جانبًا. لتعيش عليها الاتصال بالزاوية السفلى اليمنى، فيبدأ سباق أسر حول الزاوية.","31":"الأسود 31 (M4) نقلة مهمة. بدل الاندفاع إلى معركة الزاوية يصنع أولًا نقطة يجب على الأبيض الرد عليها. إنها تحضير للكو الآتي حتمًا.","33":"بالنقلة 33 (R2) يبدأ سباق الأسر في الزاوية السفلى اليمنى. أمّن الأبيض 32 (L3) أحجاره السفلية، فلا بد للأسود من مهاجمة أحجار الأبيض في الزاوية. إن أسرها عاشت أحجاره السفلية، وإلا فهي في خطر.","35":"الأبيض 34 (S2) والأسود 35 (S1): نقلات دقيقة على الخطين الأول والثاني في الزاوية. يقلّص كل طرف حريات الآخر (النقاط الفارغة حول المجموعة) ليأسر أولًا.","36":"الأبيض 36 (N2). قبل بدء الكو يلعب الأبيض أولًا قرب أحجار الأسود السفلية. حتى لو ربح الأسود الكو سيكسب أقل قليلًا: توقيت جيد.","40":"الأبيض 40 (R1) يأسر حجرًا فيتكوّن الكو أخيرًا. في الكو لا يجوز لمن أُسر حجره للتو أن يستردّه فورًا. على الأسود أولًا أن يلعب تهديدًا في مكان آخر يجب على الأبيض الرد عليه، ثم يستردّ. يفوز من يملك تهديدات أكثر.","41":"الأسود 41 (O5) أول تهديد كو. تجاهله يضع أحجار الأبيض في الأسفل يمينًا في ورطة، فيرد الأبيض بـ42 (N5)، ويستردّ الأسود بـ43 (R2). يكلّف قليلًا لكنه ضروري.","44":"الأبيض 44 (S7) تهديد الكو الأبيض. لُعب بجوار أحجار الأسود اليمنى فأجبر الأسود على الرد بـ45 (S8)، ثم استرد الأبيض بـ46 (R1). كل تهديد يحسم جزءًا آخر من اللوحة.","47":"الأسود 47 (M5)، الأبيض 48 (N6)، الأسود 49 (R2): تهديد آخر واسترداد آخر. حول أحجار الأبيض السفلية يضيف الأسود أحجارًا في الخارج شيئًا فشيئًا.","50":"الأبيض 50 (R7) يقطع أحجار الأسود اليمنى: تهديد كبير. عادة كان الأسود سيرد، لكنه يقدّم الكو. تحدث مقايضة كبيرة: يكسب الأبيض على الجانب الأيمن، ويأخذ الأسود الزاوية السفلى اليمنى.","51":"الأسود 51 (P2) يأسر حجرًا ويربح الكو. تصبح الزاوية السفلى اليمنى أرضًا حية للأسود، وتنجو أحجاره السفلية. في المقابل يتابع الأبيض بـ52 (R8) ليشطر أحجار الأسود اليمنى نصفين.","53":"الأسود 53 (R10) فكرة بارعة قلّما يجدها أحد. يأتي لنجدة الجزء العلوي من أحجار الأسود اليمنى المنقسمة من الجهة الأخرى لأحجار الأبيض. لو رد الأسود ردًا بسيطًا لأخذ الأبيض جزءًا كبيرًا من الجانب الأيمن.","56":"الأبيض 54 (S10) والأسود 55 (S11) والأبيض 56 (S9): يعيش الأبيض على الحافة اليمنى، ويكبحه الأسود من الأعلى محتفظًا بالنصف العلوي من الجانب.","59":"بعد الأسود 57 (M6) والأبيض 58 (N7) يصل الأسود 59 (R11) أحجاره اليمنى بإحكام. صار جانب الأسود الأيمن آمنًا من أعلاه إلى أسفله. تبدو المقايضة الكبيرة متكافئة تقريبًا.","60":"الأبيض 60 (S3) نقلة كبيرة. تقلّص أرض الأسود في الزاوية وتقوّي أحجار الأبيض، وتتيح لاحقًا لعب 62 (M1) كنقلة يجب على الأسود الرد عليها.","63":"الأبيض 62 (M1) يأسر حجرًا والأسود 63 (O1) يصل: انتهت المعركة الطويلة في الأسفل يمينًا مؤقتًا. للأبيض أرض في الأسفل، وللأسود جدار سميك على اليمين. وبسبب النقلة 25 جزئيًا يُعتقد أن الأبيض لعب أفضل حتى الآن. لكن جدار شوساكو سيعمل كثيرًا لاحقًا في الوسط.","65":"الأبيض 64 (G3) يمتد نحو يسار الجانب السفلي ليكبّر منطقته أكثر. والأسود 65 (G5) يغطيه من الأعلى كي لا تكبر صعودًا. يتضح النمط: الأبيض يأخذ الأرض، والأسود القوة الخارجية.","66":"الأبيض 66 (C9) على الجانب الأيسر. مع الأبيض 6 (C14) يبني هناك أيضًا إطارًا أبيض. يجمع الأبيض الأرض في الأسفل واليسار.","67":"الأسود 67 (L17) على الجانب العلوي. مستندًا إلى جداره السميك يسعى إلى إطار كبير — منطقة واسعة قد تصير أرضًا — من الأعلى نحو الوسط. وفي الوقت نفسه يضع P17 في كماشة.","69":"الأبيض 68 (J17) يدخل يسار L17 ليشطر إطار الأسود العلوي. والأسود 69 (Q17) يلتصق بـP17 فيهاجمه ويقوّي الزاوية.","70":"الأبيض 70 (O10) يتوسط جدار الأسود الأيمن وإطاره العلوي. يمنع الإطار من الالتحام عبر الوسط ويحاول الاتصال بأحجار الأبيض اليمنى.","72":"الأبيض 72 (P13) نقلة رائعة. وُضع فوق جدار الأسود مباشرة فأنشأ مأوى أبيض في قلب إطار الأسود. حتى لو طارده الأسود يستطيع الأبيض الإفلات بخفة. تقلصت آمال الأسود في الأعلى بهذه النقلة.","73":"الأسود 73 (P12) يسدّ أسفل P13 كي لا يتصل بأحجار الأبيض اليمنى. ثم يدخل الأبيض 74 (Q18) الزاوية العليا اليمنى ليقتطع من أرضها أيضًا.","77":"بعد الأسود 75 (R18) الذي يحمي الزاوية، يأتي الأبيض 76 (O13) والأسود 77 (N11). يغطي الأسود أحجار الأبيض في الوسط ليكسب الأرض بالهجوم. من هنا حتى النقلة 100 تقريبًا لا يتهاون غينان أبدًا ويتفادى كل الهجمات.","79":"الأبيض 78 (N10) يصل أحجاره في الوسط، والأسود 79 (O16) يقوّي الأعلى. لم يكسب الأسود كثيرًا من الهجوم، لكنه يحتفظ بأرض الأعلى بأمان.","80":"بالنقلتين 80 (Q12) و82 (Q13) يصل الأبيض أحجارًا بجوار جدار الأسود مباشرة. ومع شكل متين داخل إطار الأسود ستكون أرض الأسود في الأعلى يمينًا أصغر من المأمول.","83":"الأسود 83 (H3) يدخل أرض الأبيض السفلية التي كبرت كثيرًا. ثم الأبيض 84 (H2) والأسود 85 (J2): معركة دقيقة حول ما إذا كان الأسود سيعيش في الداخل أو يهرب إلى الخارج.","87":"الأبيض 86 (J3) والأسود 87 (H4) والأبيض 88 (K2): يصل الأسود أحجاره المتسللة بـG5 ويُخرجها. تتقلص أرض الأبيض السفلية ويزيد الأسود سُمكه في الوسط.","89":"الأسود 89 (F17) يقترب من D17 ويضع حجرًا أسود يسار الجانب العلوي، فيكبح تمدد الأبيض. ويحاول الأبيض 90 (M17) و92 (N17) إحياء أحجاره بين أحجار الأسود في الأعلى.","93":"بالنقلتين 93 (M18) و95 (N16) يضغط الأسود أحجار الأبيض العليا من فوق ومن تحت. لا يستطيع الأبيض أن يعيش إلا منخفضًا على الخطين الأول والثاني، وبأرض قليلة جدًا.","96":"منذ الأبيض 96 (R14) تبدأ معركة دقيقة بجوار زاوية الأسود العليا اليمنى. يفصل الأبيض جدار الأسود عن الزاوية ليُضعف أحجاره. يرد الأسود بـ97 (Q14)، ويتقدم الأبيض على الحافة اليمنى بـ98 (R12) و100 (S12).","101":"بالنقلتين 101 (T12) و103 (T13) ينزل الأسود إلى الخط الأول على الحافة اليمنى فيضيّق مساحة حياة الأبيض. تبدو نقلات الحافة صغيرة، لكنها هنا تحسم الحياة والموت.","104":"الأبيض 104 (Q10) يضرب نقطة ضعف في جدار الأسود الأيمن. بعد الأسود 105 (Q11) والأبيض 106 (P11) يذهب الأسود للأسر بالنقلة 107.","107":"الأسود 107 (P10) يأسر حجرًا أبيض. صار جدار الأسود الأيمن متصلًا بإحكام وآمنًا. ويخرج الأبيض 108 (O11) و110 (P9) نحو الوسط لحماية أحجاره القريبة من الجدار.","112":"منذ الأبيض 112 (L18) تسارع أحجار الأبيض العليا إلى الحياة. ويطوّقها الأسود بـ113 (K18) و115 (K17) و117 (K19) كي لا تخرج.","118":"الأبيض 118 (M19) يأسر حجرًا فتعيش مجموعته العليا. العيش داخل إطار الأسود يقلّص أرضه كثيرًا. لعب غينان حتى الآن ممتاز.","120":"الأسود 119 (D18) يجسّ زاوية الأبيض العليا اليسرى، ويرد الأبيض بـ120 (C17). لا يريد الأسود الزاوية، بل تقوية يسار الجانب العلوي لكسب أرض.","122":"الأسود 121 (F15) يرتّب شكله من الأعلى نحو الوسط. والأبيض 122 (C6) يلعب بجوار زاوية الأسود السفلى اليسرى ليقتطع من أرضها شيئًا فشيئًا.","124":"الأسود 123 (G2) والأبيض 124 (J1) والأسود 125 (F3): تُحسم الحدود يسار الأسفل. يأسر الأبيض هناك حجرًا ويحافظ على أرضه.","126":"الأبيض 126 (J5). الأبيض سميك في الأسفل ومستعد للتقدم نحو الوسط. بأرضه في الأسفل واليسار ومجموعته الحية في الأعلى يمينًا يتقدم الأبيض. يُقال إن معظم المحترفين الحاضرين رأوا الأبيض متقدمًا. لن يلحق الأسود بنقلات عادية.","127":"هذه هي نقلة «الأذنين المحمرّتين» الشهيرة، الأسود 127 (K11). يُقال إن هذا الحجر في وسط اللوحة يعمل في أربعة اتجاهات معًا: صعودًا يوسّع إطار الأسود، ونزولًا يوقف سُمك الأبيض، ويمينًا يسند جدار الأسود، ويسارًا يصد تمدد الأبيض. نقلة واحدة بأربع مهام. ومن هنا تبدأ المباراة، التي بدت في صالح الأبيض، بالميل تدريجيًا نحو الأسود.","128":"عندما لُعبت النقلة 127 لاحظ طبيب يراقب قريبًا أن أذني غينان احمرّتا. لم يكن يعرف الكثير عن الغو، لكنه يُروى أنه رأى في ذلك علامة اضطراب وتوقّع فوز الأسود. وبينما ظن المحترفون أن الأبيض أفضل، التقطت عين الطبيب وحدها نقطة التحول. الأبيض 128 (E18) يدافع عن الزاوية العليا اليسرى.","131":"بعد أن يقوّي الأسود يسار الأعلى بـ129 (F18)، يدخل الأسود 131 (D10) إطار الأبيض على الجانب الأيسر. ولأن الحجر 127 يسند الوسط يستطيع الأسود الاقتحام بأمان.","136":"بالنقلتين 133 (E10) و135 (D12) تتسلل أحجار الأسود اليسرى بين أحجار الأبيض وتتخذ شكلًا. ويأتي الأبيض 136 (J10) إلى الوسط ليُضعف أثر الحجر 127، فلا يمكنه ترك الوسط للأسود.","140":"الأسود 137 (H7) يغطي أحجار الأبيض السفلية، ويحاول الأبيض 138 (G10) و140 (F8) وصل أحجاره يسار الوسط. في الوسط تتشابك الأحجار ولكلا الطرفين نقاط ضعف.","143":"الأبيض 142 (E2) يتسلل إلى زاوية الأسود السفلى اليسرى. ويصل الأسود 143 (D7) و145 (D6) أحجاره وعينه على أحجار الأبيض اليسرى وعلى المتسلل في الزاوية معًا.","147":"الأسود 147 (K10) يمتد مباشرة إلى الأسفل من الحجر 127 فيشطر أحجار الأبيض في الوسط يمينًا ويسارًا. هنا يبدأ الحجر 127 في إظهار قوته الحقيقية.","150":"الأبيض 148 (K9) والأسود 149 (L9) والأبيض 150 (J11): يحاول الأبيض وصل أحجار الوسط، ويقطعها الأسود عن الأسفل. ويحط الأبيض 150 بجوار الحجر 127 مباشرة ليدخل وسط الأسود أيضًا.","155":"من الأسود 151 (J9) إلى الأسود 155 (K12) يضغط الأسود أحجار الأبيض في الوسط من الجهتين. الأسود 155 يتصل فوق الحجر 127 فيوحّد وسط الأسود مع الأعلى. المبادرة في الوسط للأسود.","160":"بعد الأبيض 156 (C5) والأسود 157 (D5) يلعب الأبيض 158 (J12) و160 (H8). يحمي أحجاره في الوسط ويستهدف ضعفًا لدى الأسود في الأسفل يسارًا. ما زالت المباراة متقاربة ولا يمكن لأحد التهاون.","162":"الأسود 161 (B8) يدخل تحت أحجار الأبيض اليسرى. والأبيض 162 (D13) يغطي أحجار الأسود اليسرى من الأعلى ليضيّق عليها.","167":"بعد تقوية الوسط بـ163 (G12) و165 (J13) يأتي الأسود 167 (C2) نقلة دقيقة تحمي الزاوية السفلى اليسرى. لو أُهملت لاستطاع حجر الأبيض 142 (E2) تهديد الزاوية. يزيل الأسود الخطر أولًا ويبني موقفًا يصعب خسارته.","169":"الأبيض 166 (E17) و168 (F16) يحاولان قطع أحجار الأسود في الأعلى يسارًا. يرد الأسود بـ169 (G16) و171 (G17) واصلًا أحجاره العليا بإحكام.","175":"الأسود 175 (G4) يأسر حجرًا أبيض. تنجو أحجار سوداء داخل منطقة الأبيض السفلية، فأرضها أصغر مما بدت. يضيق الفارق تدريجيًا.","180":"الأبيض 176 (M11) والأسود 177 (L13) والأبيض 178 (J6) والأسود 179 (M10) والأبيض 180 (M13): يمين الوسط أيضًا يضع الأبيض أحجارًا في إطار الأسود ليقلّصه. يرد الأسود محوّلًا الوسط كله إلى أرضه.","187":"من الأسود 183 (K13) إلى 187 (M14) يضغط الأسود من الأعلى على أحجار الأبيض في الوسط ويبعدها عن الأعلى. يكافح الأبيض ليعيش، لكن جدار الأسود سميك والمعركة شاقة عليه.","195":"من الأبيض 190 (G14) إلى 194 (M9) يوسّع الأبيض منافذ أحجاره في الوسط. ويقتحم الأسود 195 (L10) بينها ليكسر شكلها.","199":"مع الأسود 199 (K7) تهدأ معركة الوسط. تنجو أحجار الأبيض في الوسط بالكاد، لكن الأسود كسب أرضًا في الطريق وصارت المباراة تميل إليه. تأتي الآن النهاية: تثبيت الحدود، حيث تحسم نقطة أو نقطتان كل شيء.","208":"الأسود 203 (E19) و205 (F2) والأبيض 208 (R19): تُلعب نقلات النهاية على الحواف من الأكبر إلى الأصغر. في النهاية من المهم لعب النقلات التي يجب على الخصم الرد عليها أولًا.","212":"بالنقلتين 212 (D19) و216 (F19) يأسر الأبيض أحجارًا سوداء على الحافة العليا، ويعوّض الأسود في مكان آخر بـ213 (G11) و217 (G19). لا يتراجع أحد.","225":"الأسود 225 (L6) يأسر حجرًا أبيض ويواصل اقتطاع أرض الأبيض في منتصف الأسفل. تقترب المعركة الكبيرة الأخيرة: كو في الوسط.","228":"الأبيض 228 (N12) يأسر حجرًا فيصنع كو في الوسط. لأكثر من 80 نقلة سيتبادل الطرفان الأسر في M13 وN13. كل تهديد يُحدث مقايضة صغيرة في مكان ما. يبدأ الكو الطويل جدًا الذي سيحسم المباراة.","236":"الأبيض 236 (T8) يأسر حجرًا في منتصف الكو. يرى بعض المحللين أن إغلاق الكو هنا كان سيقلص الفارق. في الكو الطويل تحدد المقايضات المختارة النقطة أو النقطتين الأخيرتين.","262":"بالنقلتين 262 (T1) و266 (S4) يأسر الأبيض أحجارًا سوداء في الزاوية السفلى اليمنى. في الأثناء استرد الأسود في مكان آخر، ويستمر الكو مع مكاسب وخسائر لدى الطرفين.","275":"الأسود 275 (T14) يأسر حجرين أبيضين، وهذه المقايضة على الحافة العليا اليمنى لصالحه. وبجمع مقايضات الكو يحافظ الأسود على تقدمه الطفيف.","299":"الأسود 299 (J16) يأسر أربعة أحجار بيضاء دفعة واحدة. زال تهديد الأبيض في الأعلى وصار أعلى الأسود آمنًا. تجاوز الأسود آخر أزمة كبيرة في الكو.","311":"الأسود 311 (M13) يغلق الكو أخيرًا. انتهى كو الوسط الذي دام أكثر من 80 نقلة. وعبر كل المقايضات حافظ الأسود على تقدمه. لم تبق إلا نقلات نهاية صغيرة.","321":"من الأسود 317 (N1) إلى 321 (M2) تُثبَّت آخر الحدود في الأسفل. يواصل الطرفان اللعب بدقة حتى النهاية لكسب ولو نقطة واحدة.","325":"تنتهي المباراة بعد 325 نقلة، ويُظهر العدّ تقدّم الأسود بنقطتين. تعثّر الأسود قليلًا في التايشا المفضّلة لدى غينان في البداية، وكان الأبيض يُعدّ أفضل حتى منتصف اللعب. قلب شوساكو المجرى بحجر النقلة 127، وصمد في الكو الطويل، وحافظ على تقدم ضئيل. يُروى أن غينان قال لاحقًا إن قوة شوساكو لم تكن دون مستوى 7 دان. صنعت هذه المباراة اسم شوساكو، وصار لاحقًا وريث بيت هونينبو. التايشا في الافتتاح، ونقلة الأذنين المحمرّتين 127، والكو الطويل في النهاية: هذه أبرز محطات هذه المباراة العظيمة."}},"evergreen":{"t":"المباراة دائمة الخضرة","w":"أدولف أندرسن","b":"جان دوفرين","ev":"مباراة ودية (ليست في بطولة)","d":"1852","pl":"ألمانيا (على الأرجح برلين)","lead":"أندرسن، صاحب المباراة الخالدة، لعب هذه التحفة الأخرى بعد عام. في اللحظة التي يهدّد فيها الأسود بالكش مات، يحرّك الأبيض رخًا بهدوء، ثم يضحّي بالوزير وينهي بكش مزدوج. تُسمّى \"دائمة الخضرة\" لأنها لا تذبل أبدًا.","c":{"0":"مباراة نُشرت في مجلة عام 1852. الأبيض أندرسن، والأسود صديقه دوفرين. يُعتقد أنها لُعبت في برلين، لكن لا يوجد سجل يؤكد ذلك.","1":"يتقدّم الأبيض ببيدق الملك مربعين.","2":"يفعل الأسود الشيء نفسه.","3":"الحصان يهاجم بيدق e5.","4":"يحمي الأسود e5 بحصان.","5":"يخرج الفيل ويصوّب نحو f7.","6":"يُخرج الأسود فيلًا أيضًا.","7":"b4! عرض بيدق يُسمّى غامبيت إيفانز. بينما يأخذه الأسود، يقوّي الأبيض الوسط.","8":"يأخذ الأسود البيدق.","9":"c3 يطارد الفيل ويستعد لـ d4.","10":"يتراجع الفيل إلى a5.","11":"d4 يحتل الوسط.","12":"يأخذ الأسود البيدق.","13":"لا يستردّ الأبيض، بل يبيّت. سلامة الملك ونشاط القطع قبل البيادق.","14":"يتقدّم البيدق الأسود حتى d3، في عمق معسكر الأبيض.","15":"الوزير إلى b3. مع فيل c4 يصوّب نحو f7.","16":"يحمي الأسود f7 بالوزير.","17":"e5 يطارد الوزير.","18":"الوزير إلى g6.","19":"الرخ إلى e1، على العمود e ليدعم بيدق e5.","20":"يُخرج الأسود حصانًا استعدادًا للتبييت.","21":"الفيل إلى a3 يصوّب قطريًا نحو حصان e7. إذا تحرّك هذا الحصان وصل الفيل إلى f8، فصار التبييت القصير صعبًا على الأسود.","22":"يعرض الأسود بيدقًا ليُبعد قطع الأبيض.","23":"يأخذه الوزير.","24":"الرخ إلى b8 يطارد الوزير على العمود b.","25":"الوزير إلى a4.","26":"يتراجع الفيل إلى b6.","27":"يخرج حصان. صارت كل قطع الأبيض تقريبًا في اللعب.","28":"يُخرج الأسود الفيل الآخر.","29":"الحصان إلى e4، وعينه على f6.","30":"الوزير الأسود إلى f5 ويهاجم حصان e4.","31":"يأخذ الفيل بيدق d3 ويحمي حصان e4.","32":"الوزير إلى h5 يصوّب نحو حصان f3.","33":"يُضحّى بالحصان في f6 مع كش!","34":"يأخذ الأسود ببيدق.","35":"يستردّ الأبيض ببيدق ويهاجم حصان e7. وعلى العمود e يراقب رخ e1 المربع e7 أيضًا.","36":"الرخ إلى g8 يصوّب نحو g2. إذا أخذ وزير h5 في f3 صار الكش مات قريبًا.","37":"نقلة رخ هادئة إلى d1! ملك الأبيض في خطر، لكن بدل الدفاع يصوّب الأبيض نحو d7. هذه النقلة هي ما جعل المباراة \"دائمة الخضرة\".","38":"يأخذ الأسود حصان f3. الأخذ في g2 بعدها سيكون كش مات.","39":"لكن الدور للأبيض أولًا. يأخذ الرخ حصان e7 مع كش!","40":"يستردّ الأسود بالحصان من c6. صار القطر من a4 إلى d7 مفتوحًا.","41":"يُضحّى بالوزير في d7 مع كش!","42":"لا بد أن يأخذ الأسود بالملك.","43":"يتحرّك الفيل إلى f5 بكش ويفتح العمود d لرخ d1: كش مزدوج.","44":"الملك إلى e8. لو ذهب إلى c6 لأعطى الفيل كش مات في d7.","45":"الفيل إلى d7، كش.","46":"الملك إلى f8.","47":"فيل a3 يأخذ حصان e7: كش مات! فيل d7 يسيطر على e8، وبيدق f6 يسيطر على e7 وg7."}},"lasker1912":{"t":"صيد الملك","w":"إدوارد لاسكر","b":"جورج آلان توماس","ev":"مباراة سريعة ودية في نادي مدينة لندن للشطرنج","d":"1912","pl":"المملكة المتحدة (لندن)","lead":"مباراة سريعة وودية في نادٍ بلندن. يضحّي الأبيض بالوزير ويطارد الملك الأسود عبر الرقعة كلها، من g8 إلى g1. تختلف ترتيبات نقلات الافتتاح قليلًا بين السجلات، لكن الوضع بعد النقلة العاشرة هو نفسه.","c":{"0":"أكتوبر 1912، نادي مدينة لندن للشطرنج. الأبيض إدوارد لاسكر، مهندس شاب وصل لتوّه من ألمانيا، والأسود جورج آلان توماس الذي صار لاحقًا بطل بريطانيا. كانت مباراة سريعة وودية. وهي مشهورة باسم \"صيد الملك\": يُطارَد الملك الأسود من g8 حتى g1 في الطرف الآخر من الرقعة. انتقل لاسكر لاحقًا إلى أمريكا واشتهر بكتبه في الشطرنج.","1":"يبدأ الأبيض بـ d4، بيدق الوزير. يسيطر على e5 وc5 ويفتح الطريق لفيل c1.","2":"يلعب الأسود e6: وضع متين أولًا، مع التحضير لـ f5 أو d5.","3":"الحصان إلى f3. يسيطر على e5 ويساعد في حماية جناح الملك: أكثر المربعات طبيعية.","4":"يلعب الأسود f5 ويسيطر على e4، كما في الدفاع الهولندي. لكن تحريك بيدق أمام الملك يُضعفه قليلًا.","5":"الحصان الآخر إلى c3، استعدادًا لـ e4 لضرب بيدق f5.","6":"يُخرج الأسود حصانًا إلى f6: يزيد سيطرته على e4 ويستعد للتبييت.","7":"الفيل إلى g5 يصوّب نحو حصان f6. هذا الحصان مدافع مهم عن الملك الأسود، لذا يريد الأبيض إزالته مبكرًا.","8":"يضع الأسود الفيل في e7 ليحمي الحصان ويقترب من التبييت.","9":"يبادل الأبيض الفيل بالحصان. اختفى الحصان الذي كان يحمي الملك الأسود.","10":"يستردّ الأسود بالفيل. الآن يتولّى فيل f6 حماية جناح الملك.","11":"e4! يضرب الأبيض بيدق f5 ويكسب مساحة في الوسط. تنفتح الخطوط وتتحرّك قطع الأبيض بحرية أكبر.","12":"يأخذ الأسود بيدق e4. وإلا لعب الأبيض e5 ودفع قطع الأسود إلى الخلف.","13":"يستردّ الحصان ويستقر في الوسط، ينظر إلى فيل f6 والمربعين g5 وd6.","14":"يلعب الأسود b6 ليضع الفيل في b7 ويصوّب على القطر الطويل نحو حصان e4.","15":"الحصان إلى e5، مربع قوي في الوسط يرى أيضًا g4 وf7. صار الحصانان الأبيضان قريبين من جناح ملك الأسود.","16":"يبيّت الأسود. الملك في g8. لكن بغياب بيدق f توجد ثغرات كثيرة حول الملك.","17":"الفيل إلى d3. حصانه في e4 يعترضه الآن، لكن خلفه بيدق h7. ما إن يتحرّك حصان e4 حتى يصوّب هذا الفيل مباشرة نحو h7.","18":"الفيل الأسود إلى b7 يصوّب على القطر الطويل نحو حصان e4 ويقيّد قطع الأبيض.","19":"الوزير إلى h5 يصوّب نحو بيدق h7 الذي لا يحميه إلا الملك الأسود. وزير الأبيض وفيله وحصاناه كلها موجّهة نحو الملك الأسود.","20":"يضع الأسود الوزير في e7. يحمي فيل f6 ويستعد للذهاب إلى c5، لكنه لا يرى فكرة الأبيض. كان لا بد من h6 أو أخذ حصان e5. هذه نقطة التحوّل.","21":"يُضحّى بالوزير في h7 مع كش! يقدّم الأبيض أقوى قطعه مجانًا. كان لاسكر يرى الطريق كله لمطاردة الملك حتى الكش مات.","22":"لا بد أن يأخذ الأسود بالملك، فيصير الملك في h7.","23":"يأخذ الحصان فيل f6 مع كش. وفي الوقت نفسه يخلو e4، فيكشّ فيل d3 أيضًا الملك في h7: كش مزدوج. لا يمكن سدّه، فعلى الملك أن يهرب.","24":"الملك إلى h6. لو ذهب إلى h8 لقفز الحصان الآخر إلى g6 بكش مات. يُدفع الملك إلى الأمام أكثر فأكثر.","25":"يقفز الحصان الآخر من e5 إلى g4 بكش، يهاجم الملك في h6 ويدفعه أبعد.","26":"الملك إلى g5: يترك معسكره ويمشي نحو جهة الأبيض.","27":"كش ببيدق h! حتى البيادق تشارك في الصيد. على الملك أن يواصل التقدّم.","28":"الملك إلى f4. عبر منتصف الرقعة ويدخل معسكر الأبيض.","29":"كش مرة أخرى ببيدق g. بيدقان يسدّان طريق العودة على الملك.","30":"الملك إلى f3، في وسط قطع الأبيض تمامًا.","31":"يتراجع الفيل من d3 إلى e2 بكش. يُدفع الملك إلى عمق أكبر.","32":"الملك إلى g2. لم يعد الملك الأبيض في e1 بعيدًا.","33":"الرخ إلى h2، كش. أخيرًا يدخل الرخ اللعب.","34":"يصل الملك أخيرًا إلى g1. انطلق من g8 وبلغ الصف الأول في الطرف الآخر من الرقعة.","35":"يتحرّك الملك الأبيض من e1 إلى d2. ينفتح بذلك طريق رخ a1 الذي يكشّ الملك في g1 على الصف الأول: كش مات! كان التبييت الطويل سيعطي كش مات أيضًا، لكن لاسكر حرّك الملك. في مباراة سريعة، وبعد التضحية بالوزير، طارد الأبيض الملك أربع عشرة نقلة حتى أعمق زاوية في معسكره. مباراة نادرة جدًا."}},"toketsu":{"t":"مباراة الدم","w":"أكابوشي إنتيتسو","b":"هونينبو جووا","ev":"لُعبت في دار السيد ماتسودايرا حاكم سوو (على أربعة أيام)","d":"1835","pl":"اليابان (إيدو)","lead":"مباراة وُلدت من الصراع على منصب «ميجين غودوكورو»، أعلى منصب في الغو الياباني. أرسل إينوي غينان إنسيكي تلميذه أكابوشي إنتيتسو لمواجهة الميجين جووا. بعد أربعة أيام من القتال خسر إنتيتسو، ويُروى أنه سعل دمًا أمام اللوحة.","c":{"0":"إيدو، 1835. لُعبت هذه المباراة في لقاء للغو بدار السيد ماتسودايرا حاكم سوو، أحد كبار الوزراء. الأسود: أكابوشي إنتيتسو (7 دان) من مدرسة إينوي. الأبيض: هونينبو جووا، صاحب منصب ميجين غودوكورو، أعلى منصب في الغو، الذي ناله بعد صراع مع إينوي غينان إنسيكي. لم يرضَ غينان، فأرسل أفضل تلاميذه ليقول إن ميجين يخسر أمام 7 دان لا يستحق اللقب. دامت المباراة أربعة أيام وتركت واحدة من أشهر قصص الغو وأكثرها حزنًا.","1":"الأسود 1 على نقطة 3-4 في الأسفل يسارًا (C4). يبدأ إنتيتسو بهدوء، مُظهرًا أنه سيلعب أسلوبه حتى أمام الميجين.","2":"الأبيض 2 (Q3) والأسود 3 (R16) والأبيض 4 (E16): حجر في كل زاوية. الأبيض 4 على النقطة العالية 4-5، التي تفضّل الامتداد على الأرض.","5":"الأسود 5 (P17) يغلق الزاوية العليا اليمنى بحجر ثانٍ ويجعلها متينة للمعارك القادمة.","6":"الأبيض 6 (E3) يقترب مبكرًا من زاوية الأسود السفلى اليسرى. جووا هجومي منذ البداية ولا يترك للأسود وقتًا ليستقر بهدوء.","8":"الأسود 7 (R5) يقترب من Q3، والأبيض 8 (R9) يضعه في كماشة من الأعلى. يريد الأبيض إضعاف هذا الحجر الأسود على اليمين وجعله هدفًا.","9":"الأسود 9 (R11) يرد الكماشة على الأبيض 8 من الأعلى. ولأن زاوية الأسود العليا اليمنى متينة يستطيع قلب الأدوار ومهاجمة الأبيض على اليمين.","10":"الأبيض 10 (P4) يدافع عن الزاوية السفلى اليمنى، فيؤجل معركة الجانب الأيمن ويقوّي زاويته أولًا.","11":"الأسود 11 (J3) يأخذ منتصف الجانب السفلي بين E3 وP4 كي لا ينال الأبيض منطقة كبيرة هناك.","12":"الأبيض 12 (D6) يضغط من الأعلى على زاوية الأسود السفلى اليسرى، ومع E3 يحاول تطويق C4. هنا تبدأ أكبر معارك المباراة.","13":"الأسود 13 (E4) يلتصق بين أحجار الأبيض تمامًا ويفصلها قبل أن يُطوَّق. يقبل الأسود القتال وجهًا لوجه.","16":"الأبيض 14 (D4) والأسود 15 (D5) والأبيض 16 (D3): يحفر الأبيض تحت زاوية الأسود بينما يكبر الأسود صعودًا. الأحجار مقطوعة من الجانبين ولكل طرف مجموعات ضعيفة: معركة صعبة.","19":"الأسود 17 (C5) والأبيض 18 (E5) والأسود 19 (F4): يكبح الأسود E5 من الأسفل ويُبقي أحجار الأبيض منفصلة. على أحجار الأبيض في الأسفل يسارًا أن تعيش في الزاوية أو تهرب.","20":"الأبيض 20 (C3) يتسلل تحت زاوية الأسود فيأكل أرضها ويحاول العيش فيها. ويواصل الأسود 21 (B3) والأبيض 22 (B2) التبادل الدقيق داخل الزاوية.","22":"الأبيض 22 (B2) ينزل إلى الخط الثاني في الزاوية ليتخذ شكلًا حيًا هناك. تصغر زاوية الأسود، لكن أحجاره الخارجية تقوى.","23":"الأسود 23 (C7) يصعد على الجانب الأيسر ويكبح أحجار الأبيض العليا (مثل D6) من الأسفل. والأبيض 24 (G2) يمتد في الأسفل ليمنح أحجار الزاوية طريقًا للاتصال والعيش.","26":"الأسود 25 (H4) يغطي أحجار الأبيض السفلية، والأبيض 26 (E6) يقوّي العليا. المجموعة البيضاء السفلى تريد أرضًا والعليا مخرجًا إلى الوسط، والأسود يراقب الاثنتين.","27":"الأسود 27 (B4) يسد ما فوق أحجار الأبيض في الزاوية ويضيّق مساحة حياتها تمهيدًا لهجمات لاحقة.","28":"الأبيض 28 (C9) يمتد بعيدًا على الجانب الأيسر ليمنح أحجاره العليا قاعدة للعيش. كثيرًا ما يُعدّ مبالغًا فيه: نقلة عنيفة على طريقة جووا. يسعى الأسود الآن إلى معاقبتها.","31":"الأسود 29 (D8) والأبيض 30 (D9) والأسود 31 (E8): يقتحم الأسود بين C9 وأحجار الأبيض العليا فيشطر الأبيض نصفين. انفصلت C9–D9 على اليسار عن D6–E6 في الوسط.","33":"الأسود 33 (C2). يُروى أنها تفرّعة جديدة درستها مدرسة إينوي سرًّا. تضغط أحجار الأبيض في الزاوية وتهاجم في الوقت نفسه أحجاره العائمة في الوسط: هدفان معًا. إنها «نقلة سرية» أُعدّت لهزيمة الميجين، ومن هنا يتضح تفوق الأسود.","36":"الأبيض 34 (D2) والأسود 35 (B1) والأبيض 36 (F3): يسارع الأبيض إلى وصل أحجاره السفلية والعيش. في الأثناء تبقى أحجار الأبيض في الوسط بلا عون فتصير هدفًا للأسود.","38":"الأبيض 38 (A2) نقلة على الخط الأول تؤمّن عيونًا لأحجار الزاوية. حين تستقر المجموعة السفلى يستطيع الأبيض التركيز على معركة الأعلى.","40":"من الأسود 37 (G5) إلى الأبيض 40 (G7) تهرب أحجار الأبيض في الوسط صعودًا، ويطاردها الأسود عن قرب مقوّيًا نفسه في الطريق.","42":"الأسود 41 (H7) والأبيض 42 (G8): يهرب الأبيض صعودًا في الوسط ويتبعه الأسود من الخارج. كلما صعد الأبيض أكثر ازداد أسفل الأسود ويساره متانة.","43":"الأسود 43 (E9). صارت C9–D9 على اليسار محاصرة وفي ورطة، وأحجار الأبيض في الوسط لم تعش بعد. لعب إنتيتسو حتى الآن ببراعة ويُعتقد أنه تقدّم بوضوح. أمام الميجين بدت خطة إينوي ناجحة.","45":"الأبيض 44 (H8) يقود أحجار الوسط صعودًا، والأسود 45 (D11) يصعد على الجانب الأيسر ساددًا ما فوق C9–D9. تفقد أحجار الأبيض اليسرى مخارجها صعودًا ونحو الوسط.","48":"الأسود 47 (H5) والأبيض 48 (F5): يحاول الأبيض وصل أحجاره في الوسط والأسفل، ويحاول الأسود فصلها. لكل اتصال قيمته عند الأبيض.","50":"الأسود 49 (C12) يقوّي الجانب الأيسر أكثر، والأبيض 50 (C16) يتجه إلى الزاوية العليا اليسرى. يترك الأبيض مؤقتًا معركة الأسفل يسارًا الصعبة ليكسب في مكان آخر.","53":"الأسود 51 (M3) يقوّي الأسفل، والأبيض 52 (Q6) يضغط على R5 يمينًا. ويدخل الأسود 53 (G17) الجانب العلوي ليوقف نمو الأبيض في الأعلى يسارًا.","57":"بعد أن يقوّي الأبيض 54 (R6) اليمين، يأتي الأسود 55 (D17) والأبيض 56 (C17) والأسود 57 (E17): يلعب الأسود فوق زاوية الأبيض مباشرة فيقتطع منها ويمتد في الأعلى.","58":"الأبيض 58 (C14) يمتد من الزاوية العليا اليسرى نحو أحجار الأسود على الجانب. تلتقي زاوية الأبيض وجانب الأسود وجهًا لوجه.","60":"عندما يغطي الأسود 59 (J8) أحجار الأبيض في الوسط، يأسر الأبيض 60 (G4) حجرين أسودين. تتنفس أحجار الأبيض في الأسفل يسارًا أخيرًا: أبيض محاصر يأخذ ما يستطيع.","63":"الأسود 61 (O3) يضع حجرًا يمين الأسفل، والأبيض 62 (J17) يذهب إلى الأعلى، والأسود 63 (F16) يكبح زاوية الأبيض العليا اليسرى من الخارج. تنتشر شرارات القتال في أنحاء اللوحة.","66":"الأبيض 64 (M17) والأسود 65 (B13) والأبيض 66 (B14): يتسلل الأسود تحت أحجار الأبيض على الحافة اليسرى، ويحاول الأبيض تثبيت مجموعته العليا اليسرى. ما زالت C9–D9 محاصرة.","68":"الأبيض 68 (B11). اشتهرت نقلات الأبيض التالية، مع النقلة 80، بأنها نقلات جووا العبقرية، مدهشة لدرجة أن الناس قالوا إن الأشباح أرتها له. تبحث B11 عن طريق يصل C9–D9 المحاصرتين بالمجموعة العليا اليسرى. من هنا يبدأ الأبيض المحاصر هجومه المضاد.","70":"الأسود 69 (D10) يحاول منع الاتصال، لكن الأبيض 70 (E12) لا يرد في اليسار ويأخذ أولًا نقطة مفتاحية في الوسط. تبقى له موارد خفية في اليسار فلا داعي للرد فورًا. استعادة المبادرة مع ترك الهجوم ينزلق: نقلة ميجين.","72":"بعد الأسود 71 (F10) الذي يضغط وسط الأبيض، يتجه الأبيض 72 (R13) إلى الجانب الأيمن. يوقف الأبيض معركة الوسط مؤقتًا ليكبح إطار الأسود في الأعلى يمينًا.","76":"الأسود 73 (P11) والأبيض 74 (R15) والأسود 75 (Q16) والأبيض 76 (O14): يتسلل الأبيض بجوار زاوية الأسود ويضع أحجارًا تصل الجانب الأيمن بالوسط، تمهيدًا لشطر الأسود.","78":"الأسود 77 (P9) والأبيض 78 (Q9): يعيق الأبيض اتصال أحجار الأسود اليمنى (R5 وP9) بالأحجار العليا. هل سيتصل الأسود أم يُقطع؟ لحظة متوترة.","80":"الأبيض 80 (Q10) يصنع «مثلثًا فارغًا»، كتلة من ثلاثة أحجار تُعدّ عادة شكلًا سيئًا. لكنها صارت قاعدة لشطر أحجار الأسود اليمنى نصفين ومهاجمتها. تقدّم الوظيفة على المظهر، فهي المثال الكلاسيكي على نقلة قبيحة لكنها ممتازة، وآخر النقلات الثلاث الشهيرة. من هنا يبدأ هجوم الأبيض الفاصل بجدية، وتبدأ المباراة بالميل تدريجيًا نحو الأبيض.","83":"بعد الأسود 81 (S6) والأبيض 82 (S7) يدخل الأسود 83 (R3) زاوية الأبيض السفلى اليمنى. تحت الضغط على اليمين، يطلب الأسود الحياة والأرض معًا باقتحام الزاوية.","86":"الأسود 85 (S2) والأبيض 86 (R4): يقلّص الأسود حريات الأبيض من الخط الأول، ويكبح الأبيض الأسود من داخل الزاوية. يعدّ الطرفان كم نقلة بقيت قبل الأسر.","88":"من الأبيض 84 (R2) إلى الأبيض 88 (Q2) يستمر سباق أسر متقارب على الخطين الأول والثاني في الزاوية. من سيأسر أولًا؟ قد تحسمه نقلة واحدة.","91":"الأسود 91 (Q4) يأسر حجرًا أبيض فيتقدم خطوة في الزاوية. لكن الأبيض يستعد لتطويق الأسود من الخارج.","95":"الأبيض 92 (N4) والأسود 93 (R7) والأبيض 94 (Q7) والأسود 95 (O4): يلتف الأبيض حول الأسود من الخارج انطلاقًا من الأسفل، ويحاول الأسود الاتصال يمينًا وأسفل. كلما كبرت المجموعة السوداء صعب إنقاذها.","98":"الأبيض 98 (M4) يطوّق أحجار الأسود السفلية من الخارج. لا يملك الأسود شكلًا آمنًا سريعًا لا في الزاوية ولا نحو الوسط.","101":"من الأبيض 96 (N3) إلى الأسود 101 (O5) تنمو أحجار سوداء وبيضاء جنبًا إلى جنب من الأسفل نحو الوسط: تدافع يكبح فيه كل طرف الآخر من جهة.","104":"بعد الأسود 103 (P2) يأسر الأبيض 104 (R4) حجرًا أسود. في سباق الزاوية يستعيد الأبيض خطوة.","106":"الأسود 105 (N2) ثم يأسر الأبيض 106 (S5) حجرًا أسود. يحتفظ الأبيض بالزاوية السفلى اليمنى، ولا تستطيع أحجار الأسود العيش فيها فعليها الهرب إلى الخارج.","107":"الأسود 107 (Q11) يحمي مجموعته العليا على اليمين: ما دامت السفلى في ورطة فليؤمّن العليا على الأقل. ويواصل الأبيض 108 (M2) والأسود 109 (O1) معركة أسر صغيرة على الحافة السفلى.","113":"بعد الأبيض 110 (J4) والأسود 111 (K2) والأبيض 112 (H3) يأتي الأسود 113 (K6): تطل أحجار الأسود السفلية نحو الوسط بحثًا عن الحياة. عليها تأمين مخرج قبل أن يُحكم الأبيض الشبكة.","116":"الأبيض 114 (L5) والأسود 115 (L3) والأبيض 116 (L6): يضع الأبيض غطاءً فوق أحجار الأسود ويضيّق مخرجها نحو الوسط. ويقطع الأسود أحجار الأبيض السفلية محاولًا الخروج.","120":"الأسود 117 (K7) والأبيض 118 (L7) والأسود 119 (J9) والأبيض 120 (N9): يقفز الأسود إلى الوسط ويسبقه الأبيض ليسد طريقه من اليمين. صار السؤال: أيّ الأحجار تضعف أولًا؟","125":"مع الأبيض 122 (J2) والأسود 123 (K3) تتمكن أحجار الأسود السفلية بالكاد من الاتصال. ويحاول الأسود 125 (N11) وصل المجموعة العليا اليمنى بأحجار الوسط.","128":"الأبيض 126 (O7) والأسود 127 (N8) والأبيض 128 (L11): يلتف الأبيض فوق أحجار الأسود في الوسط أيضًا ويضغطها من فوق ومن تحت. خطة الشطر المعدّة منذ النقلة 80 تتشكل.","132":"من الأسود 129 (M10) إلى الأبيض 132 (K10) يقطع الطرفان بعضهما في الوسط. يحاول الأسود كسر طوق الأبيض، ويغلق الأبيض مخارجه واحدًا تلو الآخر.","137":"من الأسود 133 (L8) إلى الأبيض 136 (P10) يزداد الوسط تشابكًا. ويقفز الأسود 137 (N13) بعيدًا صعودًا ليصل الوسط بالجانب العلوي.","138":"الأبيض 138 (K8) يأسر حجرًا فيبدأ كو في الوسط. لنحو 30 نقلة يتبادل الطرفان الأسر في K8 وL8. سيحدد هذا الكو مصير أحجار الأسود في الوسط.","143":"من الأسود 139 (K9) إلى الأسود 143 (J6) تتوالى التهديدات والاستردادات. يأسر الأسود 143 حجرًا أبيض ويخفف الضغط عن أحجاره السفلية.","148":"من الأبيض 144 (K5) إلى الأبيض 148 (K8) تستمر التهديدات والاستردادات في الأسفل والوسط. ومع كل تهديد يكسب الأبيض قليلًا حول أحجار الأسود السفلية.","152":"الأبيض 152 (E11) تهديد كو يضرب نقطة ضعف في أحجار الأسود اليسرى. طوال الكو يجد الأبيض في كل مكان نقلات يجب على الأسود الرد عليها.","158":"من الأسود 155 (H2) إلى الأبيض 158 (C6) تُحدث تهديدات الكو في الأسفل والأسفل يسارًا مقايضات صغيرة. يهدد الأبيض 158 زاوية الأسود السفلى اليسرى، فيدافع الأسود بـ159 (B6).","162":"الأسود 161 (G1) والأبيض 162 (F1): يحدث الأسر على الحافة السفلى أيضًا. أثناء الكو تنتشر معارك صغيرة في كل أرجاء اللوحة.","167":"بعد أن يستردّ الأبيض 166 (K8) مجددًا، لا يواصل الأسود 167 (M1) الكو ويلعب في مكان آخر في الأسفل. وهكذا يربح الأبيض كو الوسط ويستطيع وصل أحجاره هناك. يكسب الأسود شيئًا في الأسفل بالمقابل، لكن أحجاره في الوسط تقع في ورطة.","170":"بعد الأبيض 168 (K11) والأسود 169 (H10) يتجه الأبيض 170 (P15) إلى الأعلى يمينًا. يهدّئ الوسط مؤقتًا ويستهدف المجموعة السوداء الكبيرة هناك التي لم تعش تمامًا بعد.","175":"من الأسود 171 (L13) إلى الأسود 175 (K14) يمتد الأسود صعودًا ليصل المجموعة العليا اليمنى بالوسط. ويضيّق الأبيض 174 (O17) مساحة حياة الأسود قرب الزاوية.","178":"الأبيض 178 (J14) يقفز إلى وسط الأعلى ليفصل أحجار الأسود يمينًا ويسارًا. يبدأ الآن بجدية الهجوم الفاصل المعدّ منذ النقلة 80. على الأسود الدفاع عن الجانبين معًا: موقف صعب جدًا.","182":"من الأسود 179 (K15) إلى الأبيض 182 (G14) يضغط الأبيض من الخارج على يسار الأعلى أيضًا. وعلى أحجار الأسود في الأعلى يسارًا أن تبحث عن مكان للعيش.","190":"من الأسود 183 (F14) إلى الأبيض 190 (J13) يتقاطع الطرفان بعنف على يسار الأعلى. يضع الأبيض حجرًا بعد حجر بين أحجار الأسود فيكسر شكلها.","193":"الأسود 193 (J11) يأسر حجرًا أبيض ويكافح ليتصل ويعيش. لكن أحجار الأسود على يمين الأعلى ما زالت قلقة.","199":"من الأبيض 194 (S14) إلى الأسود 199 (A16) يكبح الأبيض زاوية الأسود العليا اليمنى من الخارج، ويعمل الأسود أيضًا عند الحافة العليا اليسرى. أي مجموعة كبيرة ستضعف أولًا؟ لحظة حاسمة قبل النهاية.","201":"الأسود 201 (R14) يأسر حجرًا فيبدأ كو جديد على الجانب الأيمن في R14 وR15. حياة مجموعة الأسود العليا اليمنى تتوقف على هذا الكو.","206":"من الأبيض 202 (E14) إلى الأبيض 206 (M13) يلعب الأبيض تهديدات كو بينما يشدّ تدريجيًا الخناق على أحجار الأسود في الوسط. حتى أثناء الكو تكاد شبكة الأبيض تنغلق.","213":"من الأسود 207 (L17) إلى الأسود 213 (K18) يكافح الأسود ليتصل في الأعلى. ويمد الأبيض يده إلى الخطين الأول والثاني ليسلب الأسود «العيون»، وهي النقاط الفارغة التي تحتاجها المجموعة لتعيش.","222":"الأبيض 222 (L14) يأسر حجرًا. تبقى أحجار الأسود العليا منقسمة، وإنقاذ القسمين صار صعبًا جدًا. يؤتي هجوم الميجين الفاصل ثماره أخيرًا.","225":"الأسود 225 (R15) يغلق كو اليمين فتنجو مجموعته العليا اليمنى بالكاد. لكن الأبيض أخذ في الأثناء منتصف الأعلى، وما زال متقدمًا إجمالًا.","232":"الأسود 229 (P14) والأبيض 232 (Q14) يبدآن كو صغيرًا آخر في الأعلى يمينًا. يبحث الأسود عن فرص حتى النهاية، لكن الأبيض يرد بعناية.","239":"بالنقلتين 237 (F12) و239 (E13) يسترد الأسود أحجارًا في الأعلى يسارًا. ومع ذلك لا يعوّض ما خسره في منتصف الأعلى، ولا يتقلص الفارق الكلي.","244":"الأسود 241 (P18) والأبيض 242 (P19) والأسود 243 (P14) والأبيض 244 (N12): تستمر النقلات الصغيرة حتى النهاية، لكن الأبيض يأخذ نقاط الوسط المهمة واحدة تلو الأخرى. المباراة شبه محسومة.","246":"بعد الأبيض 246 (L8) استسلم إنتيتسو. في البداية حقق تقدمًا كبيرًا بفضل التفرّعة السرية لمدرسة إينوي، لكن جووا رد بنقلاته العبقرية بدءًا من 68 وبالنقلة 80 القبيحة لكنها ممتازة، وواصل شطر أحجار الأسود ومهاجمتها حتى قلب المباراة. يُروى أن إنتيتسو سعل دمًا على اللوحة أثناء جمع الأحجار. ربما كان مريضًا منذ مدة، وتوفي بعد ذلك بقليل. وبالنسبة لجووا الذي حافظ على لقب الميجين تُعدّ أعظم انتصار في حياته، وفشلت خطة غينان. وما زالت تُروى حتى اليوم بوصفها المباراة التي لعبها الشاب إنتيتسو بحياته."}},"deepblue1997":{"t":"انتصار ديب بلو","w":"ديب بلو (حاسوب IBM)","b":"غاري كاسباروف","ev":"المباراة السادسة من مواجهة الثأر مع ديب بلو من IBM (لقاء من ست مباريات)","d":"1997","pl":"الولايات المتحدة (نيويورك)","lead":"بطل العالم كاسباروف في مواجهة ديب بلو، حاسوب شطرنج صنعته IBM، في لقاء من ست مباريات. كانت النتيجة متعادلة بعد خمس مباريات، وانتهت الأخيرة في 19 نقلة فقط. كانت أول مرة يهزم فيها حاسوب بطل العالم في لقاء كامل من عدة مباريات.","c":{"0":"نيويورك، 11 مايو 1997. بطل العالم غاري كاسباروف في مواجهة ديب بلو، حاسوب شطرنج صنعته IBM، في لقاء من ست مباريات. كان كاسباروف قد فاز في العام السابق، لكن في مواجهة الثأر هذه مع ديب بلو الأقوى كانت النتيجة 2½–2½ بعد خمس مباريات. في المباراة الأخيرة لعب ديب بلو بالأبيض. كان العالم كله يتابع: من الأقوى، الإنسان أم الآلة؟","1":"يتقدّم الأبيض ببيدق الملك مربعين، فيحتل الوسط ويفتح الطريق للقطع.","2":"يلعب كاسباروف c6 تحضيرًا لـ d5 ضد e4: دفاع كارو-كان. إنه متين، وكان يُختار كثيرًا ضد الحواسيب.","3":"يضع الأبيض البيدق الآخر في الوسط أيضًا. بيدقان متجاوران.","4":"يلعب الأسود d5 ضد e4. يبدأ الصراع على بيادق الوسط.","5":"الحصان إلى c3 يحمي e4. نقلة طبيعية: تطوير ودفاع.","6":"يأخذ الأسود بيدق e4 ويبادل بيادق الوسط ليُصغّر وسط الأبيض.","7":"يستردّ الحصان. صار الحصان الأبيض في وسط الرقعة.","8":"يضع الأسود حصانًا في d7. فإذا خرج الحصان الآخر إلى f6 وبادل الأبيض الحصانين، يستطيع الأسود الاسترداد بهذا الحصان.","9":"يقفز الحصان إلى g5: خطة حادّة تصوّب نحو f7 وe6. يهاجم الأبيض مبكرًا قبل أن يستقر جناح ملك الأسود.","10":"يُخرج الأسود الحصان إلى f6. ازدادت القطع التي تحمي الملك.","11":"الفيل إلى d3. يصوّب قطريًا نحو h7، باتجاه جناح ملك الأسود.","12":"يلعب الأسود e6 ليقوّي الدفاع ويفتح طريق فيل f8. لكن بيدق e6 يصبح أيضًا هدفًا للحصان الأبيض.","13":"الحصان الآخر من g1 إلى f3. الأبيض جاهز للتبييت.","14":"يلعب الأسود h6 لطرد حصان g5. لكن في هذا الوضع كانت التضحية بالحصان في e6 معروفة من قبل. استغرب كثيرون أن يختار أستاذ مثل كاسباروف هذه النقلة، ويظن بعضهم أنه بدّل ترتيب النقلات سهوًا. هذه نقطة التحوّل.","15":"يُضحّى بالحصان في e6! في المقابل يحطّم الأبيض البيادق حول الملك الأسود ويمنعه من التبييت. يُقال إن ديب بلو لعب هذه النقلة من نقلات الافتتاح المخزّنة لديه مسبقًا.","16":"لا يأخذ الأسود فورًا، بل يضع الوزير في e7. على العمود e يصوّب نحو حصان e6 والملك الأبيض خلفه. إذا تحرّك الحصان صار الملك في كش، فلا يستطيع الحصان الهرب.","17":"يبيّت الأبيض ويُبعد الملك. لم يعد حصان e6 مثبّتًا. ولا يبالي الأبيض إن أُخذ الحصان.","18":"يأخذ الأسود الحصان ويتقدّم في العتاد. لكن البيادق حول الملك الأسود تحطّمت، والملك ضعيف الحماية.","19":"الفيل إلى g6، كش. بغياب بيدق f7 يصل القطر إلى الملك في e8.","20":"الملك إلى d8. لم يعد الأسود قادرًا على التبييت، وبقي الملك قرب الوسط. قطع الأسود يعترض بعضها بعضًا حول الملك.","21":"الفيل الآخر إلى f4، يصوّب نحو c7 وb8 ويضيّق مساحة الملك الأسود أكثر.","22":"يلعب الأسود b5 ليفسح مكانًا في جناح الوزير، ويُخرج الفيل إلى b7، ويعطي الملك مخرجًا.","23":"a4 يضرب بيدق b5. يريد الأبيض فتح الخطوط في جناح الوزير كي ينضمّ رخ a1 إلى الهجوم.","24":"يُخرج الأسود الفيل إلى b7 ويصوّب على القطر الطويل نحو g2. أخيرًا بدأت قطع الأسود تتحرّك.","25":"الرخ إلى e1. على العمود e ينظر إلى بيدق e6 وخلفه الوزير في e7. انضمّت كل قطع الأبيض إلى الهجوم.","26":"الحصان الأسود إلى d5، مربع قوي في الوسط: يهاجم فيل f4 ويحمي e6.","27":"يتراجع الفيل إلى g3. يواصل التصويب نحو c7 وb8 ويحافظ على الضغط على الملك الأسود.","28":"الملك الأسود إلى c8، أكثر أمانًا قليلًا، ويتيح لرخ d8 الحركة.","29":"يأخذ الأبيض بيدق b5. ينفتح العمود a، وينظر رخ a1 إلى بيدق a7.","30":"يستردّ الأسود ببيدق. لكن البيادق حول الملك الأسود تقلّ شيئًا فشيئًا.","31":"الوزير إلى d3: ينظر إلى بيدق b5 والمربع f5. قطع الأبيض تطوّق الملك الأسود شيئًا فشيئًا.","32":"يُرجع الأسود الفيل إلى c6 ليحمي بيدق b5.","33":"الفيل إلى f5! يمكن أخذه مجانًا. لكن إذا أخذه بيدق، يختفي بيدق العمود e، ويصل رخ e1 مباشرة إلى الوزير في e7.","34":"يأخذ الأسود ببيدق. الآن لا شيء على العمود e بين e1 وe7.","35":"يأخذ الرخ الوزير في e7. أعطى الأبيض حصانًا وفيلًا ورخًا، لكنه كسب أقوى قطعة: الوزير.","36":"يستردّ الأسود الرخ بالفيل. العتاد متقارب، لكن الملك الأسود بلا ملجأ تقريبًا.","37":"c4! يضرب البيدق b5 وd5 معًا، فيبدأ مدافعو الأسود بالانهيار. والوزير الأبيض جاهز للانضمام إلى الهجوم في أي لحظة. استسلم كاسباروف هنا، ربما لأنه رأى ملكه مكشوفًا أكثر من أن يوقف الهجوم. 19 نقلة فقط. كانت أول مرة يهزم فيها حاسوب بطل العالم في لقاء كامل من عدة مباريات: لحظة تاريخية. ومنذ ذلك الحين صار التعلّم والتدريب بالحاسوب أمرًا عاديًا في الشطرنج."}},"seigen1933":{"t":"مباراة 3-3 ونقطة النجم والتنغن","w":"غو سيغن","b":"هونينبو شوساي","ev":"مباراة تذكارية مع الميجين (أكثر من ثلاثة أشهر)","d":"1933–1934","pl":"اليابان (طوكيو)","lead":"لعب غو سيغن، وهو في التاسعة عشرة (5 دان)، ضد الميجين هونينبو شوساي. بالأسود افتتح على نقطة 3-3، ثم على نقطة نجم، ثم في المركز تمامًا (تنغن)، محطّمًا أعراف زمانه ومُدهشًا عالم الغو. مع توقفات كثيرة استمرت المباراة أكثر من ثلاثة أشهر، وفاز الأبيض بنقطتين.","c":{"0":"1933. في ذلك العام كان غو سيغن وصديقه كيتاني مينورو ينشران أسلوب افتتاح جديدًا يُسمّى «شين فوسيكي». أراد الجميع أن يروا كيف سيستعمله أمام الميجين.","1":"الأسود 1 على نقطة 3-3 في الأعلى يمينًا (R17). يضمن الزاوية بنقلة واحدة، لكن تأثيره نحو الخارج ضعيف، ولم يكن أحد آنذاك يراه نقلة افتتاح.","3":"الأسود 3 على نقطة النجم في الأسفل يسارًا (D4). على عكس 3-3، يهتم بالتوسع نحو الخارج.","5":"الأسود 5 يذهب إلى مركز اللوحة تمامًا: التنغن (K10). لا زاوية ولا جانب، بل الوسط. أمام الميجين عرض غو سيغن أفكاره الجديدة صراحة.","6":"3-3 والنجم والتنغن: لكل حجر أسود دور مختلف: أرض الزاوية، والامتداد نحو الخارج، وقوة الوسط. بالنقلة 6 (Q16) يلعب الأبيض بجوار حجر 3-3 الأسود مباشرة.","9":"الأسود 9 (P18). يستقر الأسود في الزاوية العليا اليمنى بشكل مضغوط وآمن، أسلوب يقدّم الأرض أولًا كما يليق بنقطة 3-3.","11":"الأسود 11 (K4) في منتصف الجانب السفلي تحت التنغن مباشرة. بالتعاون معه يطمح الأسود إلى منطقة كبيرة في الأسفل.","12":"الأبيض 12 (M3) يدخل فورًا الجانب السفلي كي لا يبني الأسود إطارًا كبيرًا. يحافظ الميجين على هدوئه ويفكك خطط الأسود واحدة تلو الأخرى.","13":"الأسود 13 (D10)، هذه المرة في منتصف الجانب الأيسر. أحجار الأسود عالية وتشكّل معًا إطارًا واسعًا.","14":"الأبيض 14 (E16) يغلق الزاوية العليا اليسرى بحجر ثانٍ. لا يرتبك الميجين أمام الأسلوب الجديد ويؤمّن الزاوية بهدوء.","21":"الأسود 21 (G10) يربط التنغن بحجر الجانب الأيسر، فينتشر نفوذ الأسود في الوسط.","28":"الأبيض 28 (D3) يتسلل تحت حجر النجم الأسود في الأسفل يسارًا ويأخذ الزاوية. يتنازل الأسود عنها مقابل قوة في الخارج.","30":"الأبيض 30 (Q12) يمتد على الجانب الأيمن ويضع غطاءً فوق زاوية 3-3 السوداء، فيُضعف امتدادها.","37":"الأسود 37 (P15) يأسر حجرًا أبيض. في الأعلى يمينًا يتصادم الطرفان في معركة متقاربة.","40":"الأبيض 40 (O10) يخرج من الجانب الأيمن نحو الوسط ويقترب من نفوذ الأسود حول التنغن.","44":"الأبيض 44 (H17) يحتل نقطة على الجانب العلوي ليوقف امتداد الأسود نحو الأعلى.","45":"الأسود 45 (R7) يبدأ العمل على موقع الأبيض في الأسفل يمينًا. تتبعه معركة طويلة من الجانب الأيمن نزولًا إلى تلك الزاوية.","59":"الأسود 59 (R4) يدخل الزاوية السفلى اليمنى أيضًا ويقلّص أرض الأبيض.","70":"الأبيض 70 (N6) يتقدم من الجانب السفلي نحو الوسط ليفصل أحجار الأسود في الأسفل يمينًا عن أحجار الوسط.","79":"الأسود 79 (L9) يقوّي الوسط حول حجر التنغن. حتى الآن تبدو المباراة متوازنة إلى حد كبير.","80":"الأبيض 80 (C6) يصعد من الزاوية السفلى اليسرى على الجانب الأيسر مستهدفًا أحجار الأسود هناك.","98":"الأبيض 98 (A11) يأسر حجرين أسودين. يعيش الأبيض بإتقان على الحافة اليسرى، ويصبح جانب الأسود الأيسر أصغر مما خُطّط له.","101":"الأسود 101 (S14) يعود إلى الأعلى يمينًا ليقلّص موقع الأبيض على الجانب الأيمن.","105":"الأسود 105 (K17) يحتل منتصف الجانب العلوي ويبدأ مهاجمة أحجار الأبيض هناك.","117":"الأسود 117 (F17) يدخل أيضًا محيط زاوية الأبيض العليا اليسرى، فيتحول الجانب العلوي كله إلى ساحة قتال.","124":"الأبيض 124 (K15) يقود أحجاره العليا نحو الوسط ويقطع بين أحجار الأسود في طريقه.","135":"الأسود 135 (E9) يأسر حجرين أبيضين. يستعيد الأسود شيئًا على الجانب الأيسر.","138":"الأبيض 138 (N18) يثبّت أرضًا على الجانب العلوي. على اللوحة كلها الوضع متقارب جدًا.","153":"الأسود 153 (K14). تشكّل أحجار الأسود في الوسط طريقًا سميكًا يصل الأعلى بالأسفل. والسؤال الحاسم: كيف سيخترق الأبيض هذا السُّمك؟","159":"الأسود 159 (F4) يدافع بثبات في الأسفل يسارًا. نقلة الأبيض التالية هي الأشهر في المباراة.","160":"الأبيض 160 (H8) يقفز إلى ثغرة في سُمك الأسود: نقلة حادة بأهداف متعددة، ومنها يبدأ الأبيض اختراق وسط الأسود. انتشرت إشاعة بأن تلميذًا، لا شوساي، هو من وجدها، لكن ذلك لم يثبت قط.","161":"الأسود 161 (J8) يردّ فورًا، لكن للأبيض أكثر من هدف.","162":"الأبيض 162 (K12) ينتقل إلى الجزء العلوي من الوسط ويهدد روابط أحجار الأسود.","172":"الأبيض 172 (F13) يصل أحجار الوسط بالأعلى يسارًا. شيئًا فشيئًا يتوقف سُمك الأسود في الوسط عن التحول إلى أرض.","178":"الأبيض 178 (N9) يدخل منطقة الأسود يمين الوسط أيضًا.","187":"بالنقلتين 187 (M6) و189 (L7) يردّ الأسود بأسر أحجار بيضاء. ومع ذلك كان الأبيض قد سبق إلى النقاط المهمة.","198":"الأبيض 198 (E12) يأسر حجرًا. وتتصل أحجار الأبيض في الأعلى يسارًا أيضًا، فيتقدم الأبيض قليلًا إجمالًا.","203":"الأسود 203 (B3). من هنا تبدأ النهاية: تُثبَّت الحدود على الحواف نقطة نقطة.","224":"الأبيض 224 (T10) يأسر حجرًا. حتى على الحافة اليمنى لا يتنازل الأبيض عن نقطة واحدة.","233":"الأسود 233 (L13) يأسر حجرين أبيضين. يواصل الأسود المطاردة حتى النهاية.","252":"تنتهي المباراة بعد 252 نقلة: فاز الأبيض بنقطتين. بلا كومي كان للأسود أفضلية صغيرة بالبدء أولًا، لكن الميجين ثبت حتى النهاية. ومع ذلك أحدثت افتتاحية غو سيغن (3-3 والنجم والتنغن) ضجة كبيرة وبشّرت بعصر جديد في الافتتاحيات."}},"century1956":{"t":"مباراة القرن","w":"دونالد بيرن","b":"بوبي فيشر","ev":"بطولة كأس روزنوالد الثالثة (بطولة روزنوالد التذكارية)","d":"1956","pl":"الولايات المتحدة (نيويورك)","lead":"بوبي فيشر، ابن الثالثة عشرة، يهزم دونالد بيرن، أحد أقوى أساتذة أمريكا. في النقلة 17 يترك فيشر وزيره يُؤخذ مجانًا، ثم يستعيد القطع واحدة تلو الأخرى، وفي النهاية تطارد قطعه الصغيرة الملك الأبيض. وأصبح فيشر لاحقًا بطلًا للعالم.","c":{"0":"نيويورك، 17 أكتوبر 1956، مباراة في بطولة. يلعب بالأسود فيشر ابن الثالثة عشرة، وبالأبيض بيرن، أحد أفضل اللاعبين الأمريكيين.","1":"يبدأ الأبيض بحصان.","4":"يلعب فيشر g6 ليضع الفيل على القطر الطويل.","8":"يبيّت الأسود: الملك في أمان أولًا.","10":"يلعب الأسود d5. يبدأ الصراع على الوسط.","15":"بـ e4 صار للأبيض بيدقان متجاوران في الوسط.","17":"الرخ إلى d1 يدعم بيدق d4. لم يبيّت الأبيض بعد.","18":"يذهب الحصان إلى b6 ويطارد الوزير في c4.","20":"الفيل إلى g4 يضغط على حصان f3.","21":"الفيل الأبيض إلى g5. ما زال الملك الأبيض في الوسط.","22":"الحصان إلى a4! يقفز إلى مربع يمكن أخذه فيه. الفكرة: إذا ابتعد حصان c3 فقد بيدق e4 حاميه.","23":"لا يأخذ الأبيض الحصان، وينقل الوزير إلى a3.","26":"يأخذ الحصان الأسود بيدق e4. وسط الأبيض ينهار.","27":"يأخذ الفيل الأبيض بيدق e7 ويهاجم في الوقت نفسه الوزير الأسود ورخ f8.","28":"الوزير إلى b6! يترك الأسود رخ f8. يعتمد فيشر على أن الملك الأبيض ما زال في الوسط.","29":"لا يأخذ الأبيض الرخ، بل يُخرج الفيل.","30":"يأخذ الحصان بيدق c3 ويهاجم رخ d1.","31":"الفيل إلى c5 يهاجم الوزير الأسود في b6.","32":"كش من الرخ على العمود e!","33":"الملك إلى f1. الآن لن يستطيع الأبيض التبييت أبدًا.","34":"الفيل إلى e6! أشهر نقلة في المباراة: يترك الأسود وزيره يُؤخذ مجانًا. وفي المقابل لديه خطة لاستعادة القطع واحدة تلو الأخرى.","35":"يأخذ الأبيض الوزير الأسود.","36":"الفيل إلى c4، كش. يبدأ الهجوم المضاد للأسود.","38":"يكشّ الحصان من e2.","40":"حين يعود الملك إلى f1 يتحرّك الحصان فيكشف كشًّا من فيل c4. وفي طريقه يلتقط الحصان بيدق d4.","44":"يعود الحصان إلى c3، كش مكشوف آخر، ويهاجم الآن رخ d1. إعطاء الكش مرة بعد مرة مع جمع القطع يُسمّى \"الطاحونة\".","46":"يستردّ الأسود الفيل. وما زال حصان c3 يهاجم رخ d1.","50":"يأخذ الحصان رخ d1. الآن استعاد الأسود أكثر من الوزير وصار متقدّمًا بوضوح.","52":"يأخذ الرخ بيدق a2 أيضًا.","56":"يبادل الأسود الرخاخ. كلما قلّت القطع كان ذلك أفضل لمن يملك أكثر.","57":"الوزير الأبيض يكشّ.","58":"يسدّ الأسود بالفيل.","64":"b5. يبدأ البيدق الأسود بالتقدّم.","68":"يذهب الملك إلى g7 ويحرّر فيل f8.","70":"الآن تطارد القطع السوداء الملك الأبيض. كش بفيل.","72":"يكشّ الحصان في g3.","74":"كش بالفيل الآخر.","76":"الفيل إلى b3، كش.","78":"يكشّ الحصان في e2.","80":"يكشّ الحصان في c3. يُطارَد الملك هنا وهناك.","82":"الرخ إلى c2: كش مات! الرخ والفيلان والحصان يعملون معًا. أظهر فتى في الثالثة عشرة كيف تلعب قطع كثيرة كفريق واحد."}},"oshiro1849":{"t":"أول مباراة قلعة لشوساكو","w":"هونينبو شوساكو","b":"ياسوي سانتشي التاسع","ev":"مباراة القلعة (المباراة السنوية في قلعة إيدو)","d":"1849","pl":"اليابان (إيدو)","lead":"كانت مباريات القلعة المناسبة السنوية الكبرى التي يلعب فيها لاعبو بيوت الغو الرسمية في قلعة الشوغون. شارك شوساكو، وهو في العشرين، لأول مرة في ذلك العام وفاز بالأسود بفارق 11 نقطة، فبدأ سجلًا مثاليًا من 19 فوزًا في 19 مباراة قلعة.","c":{"0":"1849. في العام السابق اختير شوساكو وريثًا لبيت هونينبو، وها هو يلعب أول مباراة قلعة له. يُقال إن هذه المباريات كانت تُلعب غالبًا مسبقًا في مكان آخر ثم يُعاد رصّها في القلعة فقط.","1":"الأسود 1 على نقطة 3-4 في الأعلى يمينًا (R16). كعادته يبدأ شوساكو بنقطة 3-4 هادئة.","4":"الأبيض 4 (C15) يقترب من حجر الأسود في D17 في الأعلى يسارًا. تبدأ هناك معركة مبكرة.","5":"الأسود 5 (C11) يضغط على الحجر الأبيض المقترب من الأسفل بكماشة، كي لا يستقر الأبيض بسهولة على اليسار.","12":"الأبيض 12 (C17). يأخذ الأبيض الزاوية العليا اليسرى، ويحصل الأسود على أحجار متجهة نحو الخارج: مقايضة عادلة.","13":"الأسود 13 (J17) يستفيد من الأحجار الخارجية ويمتد على الجانب العلوي.","15":"الأسود 15 (C5) يأخذ آخر زاوية فارغة في الأسفل يسارًا. صارت الزوايا الأربع كلها مشغولة.","16":"الأبيض 16 (E4) يقترب فورًا من ذلك الحجر الأسود، فتبدأ معركة في الأسفل يسارًا أيضًا.","19":"الأسود 19 (D2) يؤمّن الزاوية السفلى اليسرى بثبات: اختيار متين على طريقة شوساكو.","23":"الأسود 23 (E5) يخرج بين أحجار الأبيض ويقوّي مجموعته في الأسفل يسارًا.","29":"الأسود 29 (F11) يقوّي أحجاره على اليسار ويتطلع في الوقت نفسه إلى الوسط.","30":"الأبيض 30 (H4) يمتد في الأسفل، يضغط على مجموعة الأسود اليسرى ويبني منطقته.","31":"الأسود 31 (O3) يقترب من زاوية الأبيض السفلى اليمنى.","33":"الأسود 33 (R3) يلتصق بحجر الأبيض في الزاوية. من هنا يبني الأسود في الخارج، بينما يزحف الأبيض على الخط الثالث عند الحافة.","43":"الأسود 43 (Q8). يمتد الآن جدار أسود سميك على الجانب الأيمن. أخذ الأبيض أرض الزاوية والحافة، وكسب الأسود قوة خارجية.","44":"الأبيض 44 (L17) يدخل بين أحجار الأسود على الجانب العلوي كي لا تكبر منطقة الأسود كثيرًا.","50":"الأبيض 50 (R18) يتسلل تحت زاوية الأسود العليا اليمنى مستهدفًا أرض الزاوية.","51":"الأسود 51 (P13). مستندًا إلى الجدار، يرسم الأسود منطقة كبيرة من الجانب الأيمن نحو الوسط.","52":"الأبيض 52 (D10) يقتحم بين أحجار الأسود على الجانب الأيسر، فتتشابك الأحجار هناك.","63":"الأسود 63 (B10) يلعب على الحافة اليسرى كي لا تجد أحجار الأبيض قاعدة هناك.","65":"الأسود 65 (G3) يدخل أيضًا منطقة الأبيض في الأسفل ويقلّص أرضه.","73":"الأسود 73 (K17) يقوّي أحجاره العليا ويضغط على حجر الأبيض من النقلة 44.","76":"الأبيض 76 (P11) يقفز داخل منطقة الأسود على الجانب الأيمن. حياة هذا الحجر أو موته ستغيّر النتيجة كثيرًا.","77":"الأسود 77 (Q11) يرد من جهة جداره ويدفع الأبيض نحو الوسط: دفاع هادئ يهاجم أيضًا، على طريقة شوساكو.","80":"الأبيض 80 (N10) يهرب نحو الوسط محاولًا الإفلات من مطاردة الأسود.","85":"الأسود 85 (N12) يواصل الهجوم مع توسيع أرضه في الأعلى واليمين. الكسب عبر الهجوم: لعب بارع.","91":"الأسود 91 (J7) يلعب فوق أحجار الأبيض السفلية ويغطي منطقة الأبيض من جهة الوسط أيضًا.","100":"الأبيض 100 (S17) يحاول شيئًا في الزاوية العليا اليمنى ليقلّص أرض الأسود.","119":"الأسود 119 (R17) يدافع بثبات عن الزاوية العليا اليمنى ويصدّ محاولة الأبيض.","122":"الأبيض 122 (G6) يلتف حول أحجار الأسود في الأسفل يسارًا من الخارج محاولًا قطعها عن وسط الأسود.","131":"الأسود 131 (M5) يدقّ إسفينًا في منطقة الأبيض وسط الجانب السفلي.","140":"الأبيض 140 (B4) يحاول شيئًا في زاوية الأسود السفلى اليسرى، فتبدأ معركة أسر متقاربة على الحافة اليسرى.","156":"الأبيض 156 (A8) يأسر حجرين أسودين. تهدأ معركة الحافة اليسرى بعد أن أخذ كل طرف قليلًا.","158":"الأبيض 158 (L10). ما زالت للأبيض أحجار في الوسط، ويحاول تقليص أرض الأسود هناك.","162":"الأبيض 162 (O12) يأسر حجرًا أسود. ومع ذلك تبقى منطقة الأسود على اليمين كبيرة.","172":"الأبيض 172 (K18). من هنا تبدأ النهاية، بدءًا بالحدود على الجانب العلوي.","186":"الأبيض 186 (T16) يقتطع من أرض الأسود عند الحافة العليا اليمنى. في النهاية يلعب الطرفان أكبر النقاط أولًا.","205":"الأسود 205 (Q18) يغلق الجزء الأيمن من الجانب العلوي ويثبّت أرضه هناك.","223":"الأسود 223 (P10) يثبّت الحدود بين أرض الأسود على اليمين وأحجار الأبيض التي فرّت إلى الوسط.","233":"الأسود 233 (Q9) يأسر حجرًا أبيض. صارت أرض الأسود على اليمين آمنة تقريبًا بالكامل.","239":"الأسود 239 (A6) يأسر حجرًا فيظهر كو على الحافة اليسرى. يستمر الصراع على كل نقطة حتى النهاية.","260":"الأبيض 260 (T6) يأسر حجرًا ويصنع كو آخر عند الحافة السفلى اليمنى. يستردّ الأسود بالنقلة 263 (T5).","267":"تنتهي المباراة بعد 267 نقلة: فاز الأسود بفارق 11 نقطة. بلا مغامرات: هاجم شوساكو وترك أرضه تنمو بشكل طبيعي، فوز يشبهه تمامًا. وكانت الأولى من 19 انتصارًا متتاليًا في مباريات القلعة."}},"shilin":{"t":"مباراة «شيلين غوانغجي»","w":"الأحمر (لم يُحفظ اسمه)","b":"الأسود (لم يُحفظ اسمه)","ev":"موسوعة الحياة اليومية «شيلين غوانغجي»: «مباراة فاز فيها من أعطى النقلة الأولى، بمدفعين من الجهة نفسها»","d":"القرن الثالث عشر","pl":"الصين (سونغ–يوان)","lead":"هذا السجل مأخوذ من «شيلين غوانغجي»، وهي موسوعة للحياة اليومية جمعها تشن يوانجينغ في أواخر عهد سلالة سونغ وبدايات يوان. ويُقال إنه من أقدم سجلات الشيانغتشي الكاملة الباقية. إنها مباراة نموذجية يترك فيها اللاعب الأقوى النقلة الأولى لخصمه، وفي تسع نقلات فقط يحاصر الحصانُ الأسود العربةَ الحمراء.","c":{"0":"يزيد عمر هذا السجل على 700 عام، وهو من الزمن الواقع بين سلالتي سونغ ويوان. يرد في باب الألعاب من موسوعة «شيلين غوانغجي»، ويُقال إنه من أقدم مباريات الشيانغتشي الكاملة التي بقيت لنا. لم تُحفظ أسماء اللاعبين. يقول العنوان إن اللاعب الأقوى «أعطى النقلة الأولى» للأضعف، فهي درس يبيّن كيف يخسر الأحمر الذي يبدأ. الأحمر في الأسفل ويبدأ اللعب.","1":"ينقل الأحمر المدفع الأيمن إلى العمود الأوسط. هذا هو «المدفع المركزي» الذي يصوّب مباشرة على الجنرال الأسود، وما زال من أقوى الافتتاحيات حتى اليوم. ونرى أنه كان يُلعب قبل 700 عام.","2":"يردّ الأسود بمدفع إلى الوسط أيضًا، فيتواجه المدفعان. عندما يحرّك الطرفان المدفع من الجهة نفسها يُسمّى ذلك «مدفعين في اتجاه واحد». ومعركة المدفع ضد المدفع محبوبة منذ قرون.","3":"يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. هذا الجندي مهدَّد من المدفع الأسود ويحتاج إلى حارس. والحصان يستعد أيضًا للتقدّم.","4":"يفعل الأسود الشيء نفسه ويحمي جنديه الأوسط بحصان. يبني الطرفان أولًا قاعدة متينة.","5":"ينقل الأحمر العربة اليمنى خطوة إلى الجانب نحو عمود مفتوح. العربة أقوى قطعة على الرقعة، لذلك من الجيد تشغيلها مبكرًا.","6":"يُخرج الأسود الحصان الآخر ويترك العربتين في البيت الآن. الخطة هي تقديم القطع أولًا. لكن العربة التي تخرج متأخرة قد يصعب استخدامها في الهجوم لاحقًا.","7":"تعبر العربة الحمراء النهر دفعة واحدة وتدخل معسكر الأسود. تريد تهديد القطع السوداء، لكن بقية القطع الحمراء ما زالت في البيت، فالهجوم متسرّع قليلًا. كان يمكن أيضًا إخراج الحصان أو العربة اليسرى أولًا.","8":"يقدّم الأسود جندي العمود 3 خطوة واحدة. بهذا يفتح طريقًا للحصان ليقفز إلى الأمام لاحقًا. يكاد الأسود يدعو العربة الحمراء إلى القدوم.","9":"تأخذ العربة الحمراء جنديًا وتصوّب الآن على الحصان الأسود خلفه. كسب قطعة وتهديد أخرى يبدو رائعًا. لكن العربة تقدّمت بعيدًا جدًا ولا صديق حولها. والعربة الوحيدة في معسكر العدو يسهل مطاردتها.","10":"يقفز الحصان الأسود إلى الأمام. يهرب من العربة ويقترب من معسكر الأحمر في الوقت نفسه: مهمتان بنقلة واحدة. سيكون هذا الحصان بطل المباراة.","11":"يعيد الأحمر العربة خطوة إلى الوراء ليهاجم الحصان من الجانب. العربة تأخذ من بعيد، فلا يستطيع الحصان أن يرتاح. ومع ذلك لا تساعد هذه النقلة على إخراج قطع حمراء أخرى.","12":"يتقدّم الحصان الأسود أكثر ويعبر النهر إلى معسكر الأحمر. وفي كل مرة يهرب فيها من العربة يقترب أكثر من الجنرال الأحمر.","13":"يقدّم الأحمر جنديًا ليفتح الطريق لحصانه. الفكرة إخراجه ومبادلته بالحصان الأسود. لكن هذا يمنح الأسود وقتًا ليتقدّم أكثر.","14":"يرفع الأسود فيلًا ويهاجم العربة الحمراء. طرد عربة الخصم بقطعة دفاعية أمر فعّال جدًا. على الأحمر أن يحرّك العربة مرة أخرى، ويكسب الأسود نقلة إضافية.","15":"تنزلق العربة الحمراء جانبًا وتأخذ جنديًا آخر. صار الأحمر متقدّمًا بجنديين، لكن هذه هي النقلة الخاسرة. فالعربة الآن بعيدة عن جنرالها ولا تستطيع العودة للدفاع. كان على الأحمر أن يحتاط من الحصان، كأن يعيد العربة إلى البيت.","16":"يتوغّل الحصان الأسود أعمق ويهاجم العربة الحمراء. وهناك المزيد: إذا قفز مرة أخرى فسيكشّ الجنرال الأحمر ويهاجم في الوقت نفسه العربة في زاوية الأحمر. حصان واحد صنع تهديدين معًا.","17":"يطارد الأحمر الحصان بالعربة. لكن لم يعد من الممكن إيقافه. لم يبقَ حول الجنرال الأحمر أحد يساعد.","18":"يقفز الحصان مع كِش! وهو يهاجم أيضًا العربة في زاوية الأحمر، فإذا تنحّى الجنرال ضاعت العربة. تسع نقلات فقط، لكن المباراة تعلّمنا ماذا يحدث لعربة تندفع وحدها، ولماذا يجب أن تقاتل القطع معًا. قبل 700 عام كان اللاعبون يفكّرون في الأشياء نفسها على الرقعة نفسها."}},"qima13":{"t":"التضحية بالحصان في ثلاث عشرة نقلة («جوتشونغمي»)","w":"الأحمر (لم يُحفظ اسمه)","b":"الأسود (لم يُحفظ اسمه)","ev":"«جوتشونغمي»، الجزء الأول، المباراة الأولى","d":"1632 (سنة النشر)","pl":"الصين (مينغ)","lead":"هذه أول مباراة في كتاب «جوتشونغمي» («السرّ في داخل اليوسفية»)، وهو كتاب شيانغتشي نشره تشو جينتشن من عهد سلالة مينغ سنة 1632. يترك الأحمر للأسود أن يأخذ حصانًا مجانًا، ويندفع في الهجوم أثناء ذلك، ويُميت في ثلاث عشرة نقلة. وما زالت محبوبة بعد نحو 400 عام باسم «التضحية بالحصان في ثلاث عشرة نقلة».","c":{"0":"هذه المباراة الأولى في كتاب «جوتشونغمي» الذي طُبع سنة 1632 قرب نهاية سلالة مينغ. ويُعدّ مع «كتيّب زهر البرقوق» اللاحق أحد الكتابين الكلاسيكيين الكبيرين في الشيانغتشي. ليست مباراة حقيقية بل نموذج كُتب لتعليم خطة، لذلك لا توجد أسماء لاعبين. الأحمر في الأسفل ويبدأ، وينتهي كل شيء في ثلاث عشرة نقلة فقط.","1":"ينقل الأحمر المدفع الأيمن إلى الوسط. هذا هو «المدفع المركزي» الذي يحدّق مباشرة في الجنرال الأسود. واشتهر كتاب «جوتشونغمي» بدراسة طرق الهجوم بهذه الافتتاحية.","2":"ينقل الأسود أيضًا المدفع من الجهة نفسها إلى الوسط. هذان «مدفعان في اتجاه واحد» يتصادمان وجهًا لوجه. كل طرف يصوّب على الجندي الأوسط للآخر.","3":"يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. يحمي الجندي الذي يصوّب عليه المدفع الأسود، ويبدأ الحصان العمل.","4":"يحمي الأسود أيضًا الجندي الأوسط بحصان. حتى الآن الشكلان متماثلان.","5":"يقدّم الأحمر العربة اليمنى خطوة واحدة فقط. الآن تستطيع في النقلة التالية أن تجري جانبًا. العربة التي تتحرك جانبيًا هكذا تُسمّى «العربة الأفقية»، وتستطيع الانتقال بسرعة إلى أي جناح.","6":"يحرّك الأسود العربة خطوة إلى الجانب لتتمكن من الصعود مستقيمة. هذه «عربة مستقيمة». العربة الأفقية ضد العربة المستقيمة: طريقتان مختلفتان لاستخدام العربة وجهًا لوجه.","7":"تنتقل العربة الأفقية الحمراء إلى عمود على اليسار. هذا العمود يمرّ بجوار المستشار الأسود مباشرة، حيث الدفاع ضعيف. يستعد الأحمر للاقتحام من هنا.","8":"تعبر العربة المستقيمة السوداء النهر وتتوغّل في معسكر الأحمر. يريد الأسود أن يردّ بهجوم من عنده. لكنها نقلة تستعجل الهجوم قبل الدفاع.","9":"تندفع العربة الحمراء إلى عمق معسكر الأسود. تقف على «عين» الفيل، وهي النقطة التي يجب أن يمرّ بها الفيل، فلا يستطيع الفيل الأسود التحرك. وبجوار المستشار صارت قريبة جدًا من الجنرال.","10":"يُخرج الأسود الحصان الآخر نحو الحافة. ومن أهدافه منع العربة الحمراء من التسلّل من الجانب.","11":"ها هي التضحية بالحصان! يرفع الأحمر العربة الأخرى خطوة واحدة. يترك هذا الحصانَ في الزاوية اليسرى بلا حارس، فيستطيع المدفع الأسود أخذه مجانًا. لكن الأحمر يكسب مقابل حصان واحد الوقتَ لإدخال العربتين في الهجوم بسرعة.","12":"يأخذ المدفع الأسود الحصان الأحمر. يبدو أن الأسود كسب قطعة. لكن هذا المدفع صار بعيدًا عن بيته ولا يستطيع المساعدة في الدفاع. ويُقال إن الأفضل هنا كان رفع مستشار لتقوية الدفاع بدل الأخذ.","13":"يتقدّم المدفع الأحمر. مستخدمًا المدفع الأسود في الوسط «حاجزًا» يقفز فوقه، يصوّب الآن على الحصان الأسود خلفه. المدفع قطعة عجيبة تأخذ بالقفز فوق قطعة واحدة بالضبط.","14":"يتراجع الأسود بالحصان ليهرب. لكن هذا الحصان كان القطعة المهمة التي تحمي الجندي الأوسط. وبهروبه انفتحت ثغرة في الوسط. كان لدى الأسود دفاعات أخرى، لكن هذا كان أسوأ اختيار.","15":"يأخذ المدفع الأحمر الجندي الأوسط — كِش! بعد ذهاب الحصان الأسود صار الوسط مفتوحًا تمامًا. ومن هنا ينطلق هجوم الأحمر بسرعة.","16":"يرفع الأسود مستشارًا ليسدّ ما أمام الجنرال. هذه هي الطريقة الجيدة الوحيدة لصدّ الكِش.","17":"تصل العربة الحمراء الثانية إلى العمود نفسه. عربتان مصطفّتان في عمود واحد قوة هائلة. الخطة هي اقتحام عمق معسكر الأسود.","18":"يتنحّى الجنرال الأسود جانبًا. وإلا لحدّقت فيه العربتان الحمراوان من العمود نفسه.","19":"تأخذ العربة الحمراء الأمامية المستشار الأسود — كِش! سيأخذها المستشار الآخر فورًا، لكن هذا جزء من الخطة. يضحّي الأحمر بعربة ليحطّم حرس الجنرال الأسود. يا لها من نقلة جريئة!","20":"يأخذ الأسود العربة بالمستشار. في عدد القطع صار الأسود متقدّمًا كثيرًا. لكن بيت الجنرال صار أكثر فراغًا.","21":"تنتقل آخر عربة حمراء إلى عمود الجنرال — كِش مرة أخرى. لم يبقَ للجنرال الأسود تقريبًا أي قطعة تحميه.","22":"يضع الأسود مدفعًا أمام الجنرال ليسدّ الكِش. وضع قطعة في الوسط هكذا يُسمّى الاعتراض.","23":"تأخذ العربة الحمراء ذلك المدفع — كِش مجددًا. تواصل العربة أخذ القطع السوداء وهي تحاصر الجنرال.","24":"لا يستطيع الجنرال الأسود إلا العودة إلى الوسط. كل النقاط الأخرى تحت سيطرة القطع الحمراء.","25":"أخيرًا يقف المدفع الأحمر في الوسط: مدفعان في عمود واحد — كِش. المدفع الأمامي هو الحاجز والخلفي يضرب الجنرال: إنه مات «المدفع المزدوج». لا مكان يذهب إليه الجنرال الأسود، ويفوز الأحمر. بالتخلّي عن حصان واحد فقط فاز الأحمر في ثلاث عشرة نقلة. منذ 400 عام وهذه المباراة تعلّمنا أن الوقت ونشاط القطع قد يكونان أهم من عددها."}},"sokei1607":{"t":"أقدم مباراة شوغي محفوظة","w":"أوهاشي سوكي (الأول)","b":"هون-إنبو سانسا","ev":"أقدم مباراة مسجّلة","d":"يونيو 1607","pl":"اليابان (مكان اللعب غير مسجّل)","lead":"من بين كل مباريات الشوغي التي كُتبت نقلةً نقلة، هذه أقدم مباراة ما زالت بين أيدينا. السِّنتي هو سوكي، الذي أسّس لاحقًا بيت أوهاشي لأساتذة الشوغي. والغوتي هو سانسا، مؤسس بيت هون-إنبو للعبة غو، وكان قويًّا في الشوغي أيضًا. يفوز سوكي في 133 نقلة.","c":{"0":"أهلًا بكم، أنا Musowl. لُعبت هذه المباراة عام 1607، حين كان عصر إيدو قد بدأ للتوّ. السِّنتي أوهاشي سوكي سيُسمّى لاحقًا أول «ميجين»، أي أكبر أساتذة الشوغي في البلاد. والغوتي هون-إنبو سانسا أسّس بيت هون-إنبو للعبة غو وكان يجيد الشوغي كثيرًا؛ وكان الاثنان يلعبان كثيرًا أمام كبار القوم. بقيت ثماني مباريات بينهما بلا أفضلية، ويُقال إن سوكي فاز بسبع منها. وبعد أكثر من 400 سنة ما زلنا نستطيع إعادة كل نقلة.","1":"P-7f. تفتح هذه النقلة قطر الفيل، وما زالت حتى اليوم أكثر نقلة أولى شيوعًا. إذن كان الشوغي يبدأ هكذا قبل 400 سنة.","2":"P-3d. الغوتي أيضًا يفتح قطر فيله. الآن ينظر الفيلان أحدهما إلى الآخر عبر وسط الرقعة.","3":"S-4h. يرفع السِّنتي الفضة اليمنى. إنه يستعدّ لدفعها إلى الأمام.","5":"P-4f. يدفع السِّنتي بيدق العمود 4 ليُفسح مكانًا للفضة. وهي مرتبطة بالنقلة التالية S-4g.","6":"S-4b. الغوتي أيضًا يرفع فضة. المدافعون يتجمعون في العمود 4 لدى الغوتي.","10":"R-4b. ينقل الغوتي الرخ إلى العمود 4. يُسمّى هذا اليوم «رخ العمود الرابع»، وهو من خطط الرخ المنقول حيث يتحرك الرخ إلى اليسار. وكان يُلعب قبل 400 سنة.","11":"R-4h. رخ السِّنتي أيضًا يذهب إلى العمود 4، فيتقابل الرخّان. وسيحرّك السِّنتي هذا الرخ مرات كثيرة بحثًا عن مكان جيد للهجوم.","12":"B-3c. يتقدم الفيل خطوة ليقوّي العمود 4. جعل الغوتي هذا العمود متينًا جدًا.","16":"K-6b. ينقل الغوتي ملكه إلى اليسار. مع الرخ المنقول يختبئ الملك عادةً في الجهة المعاكسة للرخ. وكلما ابتعد عن القتال كان أكثر أمانًا.","17":"K-6h. السِّنتي أيضًا ينقل ملكه إلى اليسار. سيذهب بعدها إلى 7h ثم إلى 8g.","19":"K-7h. وصل الملك إلى العمود 7. الهدف التالي جمع الذهب والفضة حوله لبناء قلعة.","21":"G-5h. يقترب الذهب الأيمن من الملك. الذهب مدافع ممتاز، ووجوده قرب الملك يجعله في أمان.","24":"S-5c. يأتي الغوتي بفضة إلى العمود 5. ومع الفضتين في 5c و4c صار الوسط متينًا أيضًا.","29":"S-6g. تصل فضة السِّنتي قرب الملك. ومع الفضة في 6g والذهب في 7h يتكوّن جدار حول الملك.","30":"G-6c. يرفع الغوتي ذهبًا ليقوّي ما أمام ملكه. كلا اللاعبين يبني معسكره ببطء وعناية.","33":"P-8f. يدفع السِّنتي بيدق العمود 8 ليُفسح مكانًا للملك. إنه يستعدّ لـ K-8g.","35":"K-8g. يذهب الملك إلى 8g. ليست هذه قلعة مما نستعمله اليوم: الملك يقف عاليًا قرب الحافة. ونرى كيف كان لاعبو ذلك الزمان يفكرون في الدفاع.","36":"K-8b. يستقرّ ملك الغوتي في 8b. الآن كل ملك مختبئ جيدًا في زاويته.","39":"N-7g. يقفز الحصان إلى الأعلى ليستطيع القفز إلى 6e في أي وقت. يريد السِّنتي أن تساعد قطع القلعة في الهجوم أيضًا.","41":"R-3h. ينقل السِّنتي الرخ إلى العمود 3. العمود 4 لدى الغوتي قوي جدًا، فيغيّر السِّنتي مكان الهجوم.","42":"R-3b. ينقل الغوتي رخه فورًا إلى العمود 3 أيضًا. أينما ذهب رخ السِّنتي تبعه رخ الغوتي.","43":"P-2e. الآن يدفع السِّنتي بيدق العمود 2. الخطة أن ينقل الرخ إلى العمود 2 ويهاجم هناك.","44":"B-5a. يسحب الغوتي فيله إلى الخلف. يعيد ترتيب قطعه حتى تستطيع قطع أخرى صدّ هجوم على العمود 2.","45":"R-2h. عاد الرخ إلى عموده الأول، العمود 2. العمود 4 ثم 3 ثم 2: قام رخ السِّنتي برحلة طويلة.","46":"R-2b. يتبعه رخ الغوتي مرة أخرى إلى العمود 2. أينما أرسل السِّنتي رخه، استقبله الغوتي في العمود نفسه. «مطاردة الرخّين» هذه هي أجمل ما في الافتتاح.","47":"P-6e. الآن يبدأ السِّنتي القتال في العمود 6 حيث لا يوجد رخ. فبدل الهجوم حيث يراقب الرخّان أحدهما الآخر، يضرب حيث الغوتي أضعف. يبدأ وسط المباراة.","49":"Px6d. يدفع السِّنتي البيدق ويأسر. الفكرة جذب ذهب الغوتي إلى الأمام وإرخاء الدفاع حول الملك.","50":"Gx6d. يستردّ الغوتي بالذهب. ابتعد الذهب قليلًا عن ملكه، فتنفتح ثغرة صغيرة في الدفاع.","51":"P-4e. ثم يدفع السِّنتي بيدق العمود 4. إنه يهزّ دفاع الغوتي في هذا العمود أيضًا.","53":"N-3g. يقفز الحصان الآخر لينضمّ إلى الهجوم. قطع السِّنتي المهاجمة تتقدم واحدة بعد أخرى.","54":"P*6e. يُسقط الغوتي بيدقًا في 6e، المربع الذي يريد حصان السِّنتي القفز إليه. البيدق رخيص، لكنه مفيد جدًا لسدّ طريق قطعة الخصم.","56":"P-7e. يردّ الغوتي بهجوم مضاد. يضغط على العمود الذي فوق ملك السِّنتي مباشرة. إذا تحطمت البيادق فوق الملك صعب الدفاع عنه.","57":"Px7e. يأسر السِّنتي بالبيدق. وإلا لتقدم بيدق الغوتي حتى 7f.","58":"Gx7e. يستردّ الغوتي بالذهب الذي صار في 7e. يقدّم الغوتي ذهبه ليضغط على ملك السِّنتي.","59":"P*7f. يُسقط السِّنتي بيدقًا ليوقف الذهب. هذا البيدق يحمي رأس الملك.","61":"R-6i. يذهب رخ السِّنتي حتى أسفل العمود 6. يريد أن يضيف قوته إلى القتال في هذا العمود. لاحقًا ستأسره فضة الغوتي.","63":"Nx6e. يقفز الحصان من 7g ويأسر البيدق في 6e. الحصان الذي أعدّه السِّنتي منذ زمن يبدأ العمل أخيرًا.","64":"Nx6e. يستردّ الغوتي بحصانه. تبادل الطرفان الحصانين.","66":"P-8e. يضغط الغوتي من العمود 8 أيضًا. يحاول نزع البيادق أمام ملك السِّنتي واحدًا بعد آخر.","68":"P*7g. يُسقط الغوتي بيدقًا في 7g بجوار الملك مباشرة. إن أسره السِّنتي تُسحب القطعة الآسرة من مكانها، وإن لم يأسره يترقّى البيدق. إنها حيلة معروفة لكسر الدفاع ببيدق صغير.","69":"G-7i. يسحب السِّنتي الذهب إلى الخلف ليبتعد. يفضّل أن يحافظ على شكل دفاعه بدل أسر البيدق الآن.","70":"N*7e، كِش. يُسقط الغوتي حصانًا. يصل الحصان إلى الملك في 8g قافزًا فوق القطع الأخرى. يشتدّ هجوم الغوتي.","72":"Sx7e. بعد أن أسر بيدق السِّنتي الحصان، يستردّ الغوتي بالفضة ويتقدم. قطع الغوتي المهاجمة الآن بجوار ملك السِّنتي مباشرة.","74":"P*8f، كِش. يُسقط الغوتي بيدقًا آخر أمام الملك في 8g مباشرة. لم يعد الملك يستطيع البقاء هناك.","75":"K-9h. يهرب ملك السِّنتي إلى 9h على الحافة. يبتعد عن الخطر ويعيد بناء دفاعه.","77":"Px7e. الآن يأسر بيدق السِّنتي في 7f الفضة في 7e. يزيل السِّنتي قلب هجوم الغوتي ويحصل على فرصة للرد.","79":"S*7f. يُسقط السِّنتي فضة تصطدم بالذهب في 7e. تحمي رأس الملك وتحاول طرد الذهب.","81":"Sx7f. تبادل الطرفان الفضة والذهب. يقلّل السِّنتي مهاجمي الغوتي واحدًا بعد آخر.","83":"Px6e. يأسر بيدق 6f الحصان في 6e. يخسر الغوتي مهاجمًا آخر، وتزداد القطع في يد السِّنتي.","84":"S*7h. يُسقط الغوتي فضة تستهدف الرخ في 6i. سيخسر السِّنتي رخه، لكنه في الأثناء يسرّع هجومه.","85":"P*9b. من هنا يبدأ هجوم السِّنتي المضاد. بيدق يُسقط في 9b قرب ملك الغوتي يجذب الرمح إلى الأمام. تحريك القطع حول الملك يصنع ثغرات.","86":"Lx9b. يأسر الغوتي البيدق بالرمح. لكن الرمح صار في 9b وأصبح هدفًا للحصان التالي.","87":"N*8d. يُسقط السِّنتي حصانًا يهاجم معًا الرمح في 9b والذهب في 7b. مهاجمة هدفين في وقت واحد هي أبرع ما يفعله الحصان.","88":"B-5a. يسحب الغوتي فيله ليصوّب على الحصان في 8d عبر القطر. يريد أسره وإيقاف الهجوم.","89":"N*7d، كِش. يُسقط السِّنتي حصانه الآخر ويضع ملك الغوتي في كِش. الحصان يعطي كِشًا بالقفز فوق القطع، لذلك يصعب صدّه.","90":"K-8c. يصعد ملك الغوتي. وبتقدمه يقترب أيضًا من حصاني السِّنتي.","91":"Nx9b+. يأسر حصان 8d الرمح ويترقّى، فصار يتحرك مثل الذهب. دخل السِّنتي منطقة ملك الغوتي.","92":"Kx9b. يأسر الغوتي الحصان المترقّي بالملك. صار ملك الغوتي على الحافة في 9b.","93":"Bx7g. يأسر فيل السِّنتي البيدق في 7g. لم يتحرك هذا الفيل طوال المباراة، لكنه الآن يبدأ العمل. وسيكون له دور كبير لاحقًا.","94":"Sx6i+. تأسر فضة الغوتي رخ السِّنتي وتترقّى. خسارة الرخ كبيرة، لكن السِّنتي يرى أن هجومه على الملك أسرع.","95":"Gx6i. يستردّ السِّنتي الفضة المترقّية بالذهب. ذهب السِّنتي المدافع ما زال ثابتًا.","97":"P*9c، كِش. البيدق رخيص، لكنه إذا أُسقط أمام الملك مباشرة صار قويًا جدًا.","98":"K-8a. يتراجع ملك الغوتي إلى 8a. طرق هروبه تقلّ شيئًا فشيئًا.","99":"Bx8f. يأسر الفيل البيدق في 8f. وعبر قطره يرى الآن عمق معسكر الغوتي. إنه يستعدّ للنقلة الكبيرة التالية.","101":"G*9b، كِش. يعمل الذهب في 9b والبيدق في 9c معًا لطرد ملك الغوتي من الحافة.","103":"B-5c+. يطير فيل 8f حتى 5c ويترقّى إلى «حصان التنين». يتحرك مثل الفيل ومعها خطوة واحدة في أي اتجاه: قطعة قوية جدًا. دخلت قطعة السِّنتي الكبيرة قرب ملك الغوتي.","104":"K-6a. يواصل ملك الغوتي الهروب نحو العمود 6. إنه يُدفع من الحافة نحو وسط الرقعة.","105":"L*6d. يُسقط السِّنتي رمحًا. يتحرك الرمح إلى الأمام مستقيمًا مهما شاء، فيراقب العمود 6 كله.","106":"P*6b. يُسقط الغوتي بيدقًا ليسدّ طريق الرمح.","107":"+Bx4c. يأسر حصان التنين الفضة في 4c. يخسر الغوتي مدافعًا آخر.","108":"N*5b. يُسقط الغوتي حصانًا ليقوّي دفاعه. الوضع صعب، لكن الغوتي يواصل القتال.","109":"K-8g. هنا يرفع السِّنتي ملكه مرة إلى 8g. يبدو أنه يعطي الملك مساحة أكبر قبل أن يردّ الغوتي.","110":"R*8i، كِش. يردّ الغوتي بإسقاط رخ مع كِش. الغوتي أيضًا يحاول الإمساك بملك السِّنتي.","112":"P-7g+، كِش. يترقّى البيدق إلى «توكين» ويعطي كِشًا. التوكين يتحرك مثل الذهب، لكن إن أُسر لا يحصل الخصم إلا على بيدق.","114":"Rx6i+. يأسر الرخ الذهب ويصير تنينًا. فقد ملك السِّنتي مدافعيه، وصارت المباراة سباقًا: من يمسك ملك الآخر أولًا؟","115":"S*5c. يُسقط السِّنتي فضة ليضيّق الشبكة حول ملك الغوتي. الضغط على ملك الخصم حتى وملكك في خطر هو جوهر مثل هذا السباق.","116":"S*6f، كِش. يُسقط الغوتي فضة ويعطي كِشًا. على ملك السِّنتي أن يهرب.","117":"K-8f. يهرب الملك إلى 8f. لملك السِّنتي مساحة واسعة إلى الأعلى.","119":"K-9e. يواصل الملك حتى 9e على الحافة. هنا تكاد قطع الغوتي لا تصل إليه. صار ملك السِّنتي آمنًا مؤقتًا، فيستطيع التركيز على الهجوم.","120":"P-6c. يدفع الغوتي بيدقًا للدفاع. لكن دفاع الغوتي لم يعد كافيًا.","121":"S*6b. هنا يبدأ السِّنتي الإنهاء. يُسقط فضة داخل معسكر الغوتي ليأسر القطع التي تحرس الملك.","122":"Bx6b. يأسر الغوتي الفضة بالفيل.","123":"Sx6b+. تأسر فضة 5c الفيل وتترقّى. يخسر الغوتي قطعة كبيرة.","125":"Nx6b+. ويأسر حصان 7d الذهب ويترقّى أيضًا. قطعةً بقطعة، يُعرّي السِّنتي دفاع الغوتي.","126":"Kx6b. يأسر الغوتي بالملك. لكن لم يبقَ تقريبًا أي مدافع حول ملك الغوتي.","127":"B*5c، كِش. يُسقط السِّنتي الفيل الذي أسره للتو. استعمال القطع المأسورة فورًا هو ما يجعل الشوغي مثيرًا جدًا.","129":"G*8d، كِش. يغلق الذهب طريق هروب الملك من الأعلى.","131":"P*7c، كِش. لا خيار لملك الغوتي إلا أن يعود إلى الخلف.","133":"Lx6c+. يأسر الرمح البيدق في 6c ويترقّى. رأى سانسا أنه إذا دخلت قطعة إلى 6b في النقلة التالية فلن يبقى للملك مهرب، فاستسلم هنا. يفوز سوكي في 133 نقلة. أبرز ما فيها: «مطاردة الرخّين» في الافتتاح، وشدّ الحبل بالبيادق والأحصنة في الوسط، والنهاية التي ضحّى فيها السِّنتي برخه ليسابق نحو الملك. تُظهر هذه المباراة كيف ترتبط أفكار أستاذ عاش قبل 400 سنة بشوغي اليوم."}},"hu1960":{"t":"هو رونغهوا ابن الخامسة عشرة يهزم يانغ غوانلين","w":"يانغ غوانلين","b":"هو رونغهوا","ev":"البطولة الوطنية الفردية الخامسة للشيانغتشي، الجولة 3","d":"28 أكتوبر 1960","pl":"بكين","lead":"كان يانغ غوانلين قد فاز بالبطولة الوطنية ثلاث مرات. وأمامه بالقطع السوداء جلس هو رونغهوا، ابن الخامسة عشرة، في أول بطولة وطنية له. تخلّى هو عن مدفع مبكرًا ليمسك بزمام المبادرة، ثم فاز في نهاية طويلة. وفاز هو بالبطولة ثم بعشرة ألقاب وطنية متتالية، لذلك تُذكر هذه المباراة على أنها لحظة انتقال التاج من البطل القديم إلى الجديد.","c":{"0":"هذه الجولة 3 من البطولة الوطنية الفردية الخامسة للشيانغتشي في بكين سنة 1960. يلعب بالأحمر يانغ غوانلين، الفائز بالبطولة الأولى سنة 1956 وبثلاث من البطولات الأربع التي أُقيمت حتى ذلك الحين — أقوى لاعب في زمنه. ويلعب بالأسود هو رونغهوا من شنغهاي، عمره 15 عامًا فقط، وهذه أول بطولة وطنية له. توقّع الجميع فوز الأحمر، لكن هذه المباراة ستغيّر تاريخ الشيانغتشي.","1":"ينقل يانغ المدفع الأيمن إلى الوسط. المدفع المركزي يصوّب مباشرة على الجنرال الأسود، وكانت هذه الافتتاحية التي درسها يانغ أعمق دراسة.","2":"يُخرج هو حصانًا ليحمي الجندي الأوسط. إخراج الحصان مبكرًا يهيّئ للدفاع والهجوم معًا.","3":"يُخرج الأحمر أيضًا حصانًا، فيحمي الجندي الأوسط وهو يقدّم قطعه. يؤمّن الطرفان الوسط أولًا.","4":"يقدّم الأسود مبكرًا جندي العمود 7. يكبح الحصان الأحمر ويفتح طريقًا لحصانه. في هذا الوضع يُخرج معظم اللاعبين عربة أولًا.","5":"ينقل الأحمر العربة اليمنى خطوة إلى الجانب نحو عمود مفتوح.","6":"يُخرج الأسود أيضًا عربة إلى الجانب. يريد الطرفان تشغيل أقوى قطعة، العربة، مبكرًا.","7":"هنا يقدّم الأحمر جنديًا. كثيرون كانوا سيرسلون العربة إلى ما وراء النهر، لكن يانغ يقود اللعب نحو ترتيب المدافع الذي يحبه.","8":"يتقدّم المدفع الأسود حتى النهر ويقف أمام العربة اليمنى الحمراء مباشرة. هذه الخطة، «المدفع الأيسر يحبس العربة»، تُبقي العربة محبوسة في البيت. كانت فكرة جريئة لمنع يانغ من الوصول إلى ترتيبه المفضّل.","9":"يُخرج الأحمر الحصان الآخر، فيطوّر الجناح الأيسر ويستعد للرد.","10":"يرفع الأسود فيلًا ليقوّي الدفاع. الأفيال لا تعبر النهر؛ مهمتها حراسة بيت الجنرال.","11":"يندفع المدفع الأحمر إلى عمق معسكر الأسود، يأخذ حصانًا ويكشّ! إنها مبادلة مدفع بحصان. فعل ذلك مبكرًا هكذا يكلّف وقتًا غالبًا، لكن يُقال إنها هنا نقلة مقبولة.","12":"يستعيد الأسود المدفع بالعربة. صارت القطع متعادلة من جديد، وخرجت العربة السوداء بشكل طبيعي.","13":"يُخرج الأحمر العربة اليسرى أيضًا. يريد طرد المدافع السوداء وتحريك عرباته.","14":"يقدّم الأسود المدفع الآخر أيضًا حتى النهر، فيحبس العربة اليسرى الحمراء. الآن أمام كل عربة حمراء مدفع. بدأ الأحمر يضيق.","15":"يأخذ الأحمر الحصان نحو النهر. في ذهنه تهديدان: أخذ الجندي الأوسط بالحصان، أو تقديم جندي لمهاجمة المدفع الأسود.","16":"يرفع الأسود مستشارًا ليحرس الوسط. وبهذا يمنع الحصان من أخذ الجندي الأوسط مع كِش.","17":"يقدّم الأحمر الجندي. فينفتح الطريق الذي كان الجندي يسدّه، والآن يستطيع الحصان الأحمر أخذ المدفع الأسود. المدفع مهدَّد.","18":"هذه أشهر لحظة في المباراة. لا ينقذ الأسود المدفع، بل يقدّم العربة ليهاجم الحصان الأحمر. يتخلّى هو عن مدفع ليحافظ على شكل هجومه. كان خصمه بطلًا ثلاث مرات وهو في الخامسة عشرة، ومع ذلك اختار الاندفاع على حساب القطع — فدُهش المتفرجون.","19":"يأخذ الحصان الأحمر المدفع الأسود. صار الأسود ناقصًا قطعة. وفي المقابل تضغط العربة السوداء من الجانب على العربة والحصان الأحمرين.","20":"يأخذ المدفع الأسود الآخر الجندي الأوسط — كِش! يبدأ الهجوم المضاد للأسود. على الأحمر أن يرفع مستشارًا ليحمي الجنرال.","21":"يرفع الأحمر مستشارًا ليسدّ الكِش. لكن المدفع الأسود ما زال مغروسًا في عمق معسكر الأحمر.","22":"تأخذ العربة السوداء العربة الحمراء. عندما ابتعد المدفع قبل قليل انفتح طريق العربة.","23":"يستعيد الأحمر بالحصان — عربة مقابل عربة. ما زال الأسود ناقصًا قطعة، لكن قطعه تعمل بشكل أفضل.","24":"يتقدّم الحصان الأسود حتى النهر. ومن الأفكار مطاردة الحصان الأحمر بعد ذلك.","26":"ينزلق المدفع الأسود ويقف ملاصقًا للحصان الأحمر. حصان الشيانغتشي لا يستطيع التحرّك في اتجاه إذا كانت قطعة ملاصقة له من تلك الجهة («ساق» الحصان). ومع ساق مسدودة بالمدفع يكاد الحصان الأحمر لا يتحرك.","28":"يقدّم الأسود الجندي الأوسط. لاحقًا سيصبح هذا الجندي مهاجمًا مهمًا في معسكر الأحمر.","30":"يأخذ الحصان الأسود جنديًا ويتسلّل إلى معسكر الأحمر. شيئًا فشيئًا يستعيد الأسود ما خسره.","32":"يعود الحصان الأسود إلى الوسط. يتجنّب المبادلة مع الحصان الأحمر ويحتل نقطة وسطى جيدة.","34":"يتراجع المدفع الأسود نقطة واحدة. يستعد للانزلاق ومهاجمة الحصان الأحمر.","36":"ينزلق المدفع الأسود، ومستخدمًا عربته حاجزًا، يهاجم الحصان الأحمر. المدفع يأخذ بالقفز فوق قطعة واحدة بالضبط.","38":"يقفز الحصان الأسود ويهاجم العربة الحمراء. وبابتعاده يزيل أيضًا الحاجز الذي كان المدفع الأحمر يحتاجه لمهاجمة العربة السوداء.","40":"كشّ المدفع الأحمر، فأنزل الأسود المستشار ليسدّ. الأحمر يقاوم بقوة.","42":"يأخذ المدفع الأسود الحصان الأحمر! يستعيد الأسود المدفع الذي تخلّى عنه في الافتتاح. القطع متعادلة، وللأسود جندي زائد، وكل قطع هجومه الثلاث عبرت النهر. الأسود أفضل بوضوح.","44":"يقدّم الأسود جنديًا ويعرضه مجانًا. إذا أخذه الأحمر صارت خطة خفية ممكنة — نقلة تنظر بعيدًا.","45":"يأخذ الأحمر الجندي بفيل. الآن على الأحمر أن يحذر خطة الأسود.","46":"يعرض الأسود الحصان أيضًا. إذا أخذه الحصان الأحمر، يستطيع المدفع الأسود أن يكشّ ويكشف في الوقت نفسه هجومًا على العربة الحمراء.","47":"لا يأخذ الأحمر الحصان، بل يعيد حصانه إلى الوراء. البطل القديم يانغ لا يقع في الفخاخ بسهولة.","48":"تنزلق العربة السوداء جانبًا وتتحرّر من التثبيت. الآن تستطيع العربة التحرك بحرية من جديد، للهجوم أو للدفاع.","50":"يدخل المدفع الأسود إلى الوسط ويحدّق مباشرة في الجنرال الأحمر — موقع قوي جدًا.","52":"يقفز الحصان الأسود إلى الأمام مجددًا. المدفع والحصان يعملان معًا في الوسط.","56":"يذهب الحصان الأسود حتى الحافة ويصوّب على جانب الجنرال الأحمر. للحصان على الحافة نقلات أقل، لكن مهمته هنا مهمة: تهديد ملجأ الجنرال.","58":"يتقدّم الجندي الأوسط الأسود أكثر ويضغط على معسكر الأحمر. بعد عبور النهر يستطيع الجندي التحرك جانبًا أيضًا، فيصبح أقوى بكثير.","60":"تتبادل المدافع. أخذ المدفع الأحمر المدفع الأسود، ثم استعاد الجندي الأسود المدفع الأحمر. صار الجندي الأسود قريبًا من معسكر الأحمر.","62":"تأخذ العربة السوداء أحد الفيلين الأحمرين. يفقد دفاع الأحمر قطعة أخرى.","64":"يكشّ الحصان الأسود! يسدّ الأحمر ساق الحصان بالعربة. في الشيانغتشي يمكن إيقاف كِش الحصان بوضع قطعة ملاصقة له.","66":"يتراجع الحصان الأسود مؤقتًا. يواصل الكِش وهو يبحث عن أفضل مربع له.","70":"يكشّ الحصان الأسود مرة أخرى. لا تستطيع العربة الحمراء مغادرة جانب الجنرال، فلا تشارك في الهجوم.","72":"يعود الحصان الأسود إلى الحافة. يُبقي العربة الحمراء مقيّدة بينما يخطط الأسود للخطوة التالية.","76":"تأخذ العربة السوداء الفيل الأحمر الآخر أيضًا. صار الجنرال الأحمر وحيدًا جدًا.","82":"تأخذ العربة السوداء الحصان الأحمر. يُبادَل هنا الحصان الأحمر الذي قاتل بجد.","83":"يستعيد الأحمر الحصان الأسود بالعربة. بعد تبادل الحصانين صارت الرقعة أوضح بكثير. الآن المعركة بين العربة والجنود في الجانبين.","90":"يأخذ الجندي الأسود أحد المستشارين الحمر! الجندي قطعة صغيرة، لكنه في عمق معسكر الخصم يصبح قويًا بما يكفي ليُبادل بمستشار.","91":"يستعيد الأحمر الجندي بالمستشار الآخر. جندي مقابل مستشار — صار الجنرال الأحمر أقل حماية.","92":"تأخذ العربة السوداء جنديًا أحمر. في النهاية يحدّد عدد الجنود الباقين من يفوز.","98":"تأخذ العربة السوداء جنديًا آخر. لم يبقَ للأحمر إلا قليل من الجنود. خطوة بخطوة يتجه الأسود نحو وضع أسهل للفوز.","99":"تأخذ العربة الحمراء في المقابل فيلًا أسود. العربتان تتبادلان الضربات، قطعة لكل منهما.","104":"يبدأ الأسود بدفع الجندي الذي على الحافة. إيصال هذا الجندي إلى عمق معسكر الأحمر هو طريق الأسود إلى الفوز.","112":"تقف العربة السوداء خلف الجندي لتحميه. العربة والجندي معًا فريق قوي جدًا.","115":"تأخذ العربة الحمراء أحد الجنود السود. بقي للأسود جندي واحد. والأحمر لم يستسلم بعد.","123":"يقدّم الأحمر الجندي. لكن يُقال إن سحب العربة لحماية الجنرال كان أفضل هنا. صارت هذه النقلة نقطة التحول في المباراة.","124":"يتحرك الجندي الأسود جانبًا نحو الجنرال الأحمر. يتقدّم الجندي خطوة واحدة فقط كل مرة، لكنه كلما اقترب من الجنرال صار أخطر.","126":"تتراجع العربة السوداء وتهاجم الجندي الأحمر. على الأسود مراقبة ذلك الجندي، وإلا استطاع الأحمر أن يرد به.","134":"وصل الجندي الأحمر إلى آخر الرقعة، لكن العربة السوداء طاردته طوال الطريق. الجندي الذي يبلغ النهاية لا يستطيع التقدّم بعد ذلك، بل يتحرك جانبًا فقط.","136":"تأخذ العربة السوداء آخر جندي أحمر. للأسود عربة وجندي ومستشاران، وللأحمر عربة ومستشار واحد. وبجندي زائد صار فوز الأسود واضحًا.","140":"تكشّ العربة السوداء! لا يستطيع الجنرال الأحمر إلا التراجع.","144":"يتقدّم الجندي الأسود مرة أخرى وصار الآن بجوار الجنرال الأحمر مباشرة. مع تعاون الجندي والعربة لم يعد الجنرال الأحمر في أمان.","148":"يتحرك الجنرال الأسود أيضًا جانبًا. في النهاية يكون الجنرال قطعة مقاتلة أيضًا، تتحكّم في المكان الذي تستطيع قطع الخصم الذهاب إليه.","150":"تتراجع العربة السوداء، مستعدة للدفاع والهجوم معًا. إنها تجهّز العربة لأفضل مربع للضربة الأخيرة.","152":"تدخل العربة السوداء العمود 4، ولا يعود الأحمر قادرًا على الصمود. حُسمت المباراة: فاز هو رونغهوا ابن الخامسة عشرة. تضحية جريئة بمدفع في الافتتاح، وتعاون الحصان والمدفع في وسط اللعب، ولعب دقيق في نهاية طويلة — كانت في هذه المباراة الثلاثة كلها. فاز هو بالبطولة وصار بطلًا وطنيًا عشر مرات متتالية من 1960 إلى 1979."}},"soei1790":{"t":"سوئي الشيطان يهزم الميجين بلا أفضلية","w":"أوهاشي سوئي (السادس)","b":"أوهاشي سوكي (التاسع)","ev":"أوشيرو شوغي (المباراة السنوية في قلعة إيدو)","d":"1790","pl":"اليابان (إيدو)","lead":"لعب أوهاشي سوئي، الملقّب بـ«سوئي الشيطان»، هذه المباراة بلا أفضلية ضد ميجين ذلك الزمان أوهاشي سوكي التاسع في مباريات القلعة. في تلك السنة كانا يتناوبان بين مباريات بلا أفضلية ومباريات بأفضلية الرمح، وتُذكر هذه المباراة تحفةً نادرة. فاز سوئي في 121 نقلة.","c":{"0":"أنا Musowl. كانت مباريات القلعة (أوشيرو شوغي) حدثًا سنويًا كبيرًا تلعب فيه بيوت الشوغي أمام الشوغون. السِّنتي أوهاشي سوئي كان قويًا جدًا حتى لُقّب «سوئي الشيطان»، وصار لاحقًا الميجين التاسع. والغوتي أوهاشي سوكي التاسع كان قد صار ميجين قبل سنة واحدة فقط. إنها مباراة الميجين ضد الميجين القادم. نشر سوئي فكرة بناء دفاع متين أولًا ثم الهجوم، وهي قريبة جدًا من شوغي اليوم، ولذلك يُسمّى أبا الشوغي الحديث.","1":"P-7f. تفتح النقلة الأولى قطر الفيل. من هنا يبني سوئي خطة للهجوم بقطع الجانب الأيمن.","3":"P-2f. يدفع السِّنتي البيدق الذي أمام الرخ. دفع هذا البيدق مبكرًا للضغط على الخصم من الأفكار التي كان سوئي يقدّرها.","4":"P-4d. يدفع الغوتي بيدقًا يغلق قطر فيله. يتجنب تبادل الفيلين ويستعدّ لمباراة هادئة.","5":"S-4h. يرفع السِّنتي الفضة اليمنى ليستعملها في الهجوم والدفاع.","7":"P-5f. يدفع السِّنتي بيدق الوسط ليسهل خروج الفضة والذهب.","9":"P-3f. يدفع السِّنتي بيدق العمود 3 أيضًا ليفتح طريق قفزة الحصان. إنه يستعدّ لـ N-3g.","11":"P-2e. يدفع السِّنتي بيدق الرخ أكثر. الآن يجب على الغوتي حماية العمود 2 بالفيل أو بفضة.","12":"B-3c. يحمي الغوتي العمود 2 بالفيل. وإلا لاخترق رخ السِّنتي العمود 2 بعد P-2d.","15":"G-5h. يقرّب السِّنتي ذهبًا من الملك ويبدأ ببناء دفاعه.","17":"N-3g. يقفز الحصان إلى الأعلى ويكتمل شكل هجوم السِّنتي. من هنا يستطيع القفز إلى 4e أو 2e ليصل إلى معسكر الغوتي.","20":"R-5b. ينقل الغوتي رخه إلى عمود الوسط 5. يُسمّى هذا اليوم «الرخ الأوسط». الهدف هزّ معسكر السِّنتي من الوسط.","22":"P-5e. يدفع الغوتي فورًا بيدق العمود 5 نحو بيدق السِّنتي. وكما يحب الرخ الأوسط، يبدأ القتال في الوسط.","23":"Px5e. يأسر السِّنتي البيدق. وإلا لأسر بيدق الغوتي البيدق في 5f.","24":"S-6d. يقدّم الغوتي فضة ليستعيد البيدق في 5e.","25":"P-5d. يدفع السِّنتي البيدق المأسور أبعد. وضعه أمام رخ الغوتي مباشرة يجبره على أسره، فتبتعد قطع الغوتي عن أفضل مربعاتها.","26":"Rx5d. يأسر الغوتي البيدق بالرخ، الذي خرج إلى 5d وصار قويًا في الوسط.","27":"B-7i. يسحب السِّنتي فيله إلى الخلف. بعد تراجعه مرة يستطيع لاحقًا العمل على قطر آخر. سيخرج هذا الفيل لاحقًا إلى 2d.","28":"K-4a. يضع الغوتي ملكه في 4a. مع الرخ الأوسط يختبئ الملك عادةً في اليمين.","29":"P*5f. يُسقط السِّنتي بيدقًا كي لا يتقدم رخ الغوتي في العمود 5.","30":"P*5e. يُسقط الغوتي بيدقًا أيضًا ويصطدم مجددًا في العمود 5. يستمر شدّ الحبل في الوسط.","32":"Px5f. يأسر بيدق الغوتي بيدق السِّنتي ويعضّ داخل معسكره.","34":"S-5e. يُخرج الغوتي الفضة ليسيطر على العمود 5.","35":"Gx5e. يأسر السِّنتي الفضة بالذهب. سيتبادل الطرفان الذهب والفضة.","36":"Rx5e. يستردّ الغوتي الذهب بالرخ. بعد تبادل الذهب بالفضة يهدأ القتال في الوسط. صار في يد السِّنتي فضة، وفي يد الغوتي ذهب.","37":"P*5f. يُسقط السِّنتي بيدقًا ليغلق العمود 5، فلا يعود رخ الغوتي قادرًا على الدخول.","38":"R-5b. يسحب الغوتي رخه. انتهى قتال الوسط مؤقتًا.","39":"G-5h. يرفع السِّنتي ذهبه الآخر ويقوّي ما حول الملك.","41":"K-6i. يبدأ ملك السِّنتي بالتحرك إلى اليسار، بعيدًا عن الوسط حيث دار القتال.","43":"K-7h. يصل الملك إلى 7h. من هنا سيبني السِّنتي قلعة من الذهب والفضة. كان سوئي يؤمن بالدفاع أولًا ثم الهجوم.","44":"R-8b. يعيد الغوتي رخه إلى العمود 8. بما أن الوسط هدأ، يريد الآن الهجوم من العمود 8.","45":"S*7g. يُسقط السِّنتي الفضة التي في يده أمام الملك. يستعدّ مسبقًا لهجوم الغوتي من العمود 8.","47":"P-1f. يدفع السِّنتي بيدق الحافة. بيدق الحافة المتقدم يفيد لاحقًا في هجوم من الحافة أو كطريق هروب للملك.","49":"P-1e. يتقدم بيدق الحافة خطوة أخرى. السِّنتي يستعدّ بعناية.","51":"P-2d. هنا يبدأ السِّنتي هجومه، فيصادم ببيدق الرخ الذي ظل يدفعه منذ البداية. يبدأ هجوم السِّنتي.","53":"Bx2d. يطير الفيل الذي تراجع إلى 7i على القطر حتى 2d. الآن نفهم لماذا سحبه السِّنتي في النقلة 27.","54":"Bx2d. يأسر الغوتي الفيل بفيله. تبادل الطرفان الفيلين.","55":"Rx2d. يستردّ السِّنتي بالرخ، الذي يراقب من 2d معسكر الغوتي. صار لكل طرف فيل في يده.","56":"P*2c. يُسقط الغوتي بيدقًا ليسدّ طريق الرخ.","57":"R-2f. يسحب السِّنتي رخه. لا يتوغل كثيرًا ويعيد الرخ إلى مكان آمن.","59":"P-4f. يدفع السِّنتي بيدق العمود 4 استعدادًا للهجوم التالي. بعد العمود 2 تقضي الخطة بالهجوم من العمودين 3 و4.","60":"R-8d. يرفع الغوتي رخه ليستطيع استعماله جانبيًا أيضًا.","61":"P-3e. يدفع السِّنتي بيدق العمود 3 ليصطدم ببيدق الغوتي في 3d.","63":"P-4e. يصادم السِّنتي ببيدق العمود 4. إنه يهزّ الغوتي في عدة أعمدة معًا: 3 و4 و5.","65":"P-5e. يقدّم السِّنتي بيدق العمود 5 أيضًا، فيدقّ إسفينًا في وسط دفاع الغوتي.","66":"P*5c. يُسقط الغوتي بيدقًا ليحمي العمود 5.","67":"Px3d. يأسر بيدق السِّنتي البيدق في 3d. لاحقًا سيصل إلى 3c ويترقّى ليضغط على ملك الغوتي.","68":"P-8f. يردّ الغوتي ويدفع بيدق العمود 8 ليشعل النار قرب ملك السِّنتي.","69":"Sx8f. يأسر السِّنتي بالفضة. تتقدم فضة 7g وتدافع دون أن تهمل الملك.","70":"B*4d. يُسقط الغوتي الفيل الذي في يده. عبر أقطاره يراقب معسكر السِّنتي، مستعدًا للدفاع والهجوم.","71":"R-2i. يسحب السِّنتي الرخ حتى الأسفل. يبتعد عن خط الفيل ويظل يراقب العمود 2.","72":"P-6e. يدفع الغوتي بيدق العمود 6 ليهزّ ما حول ملك السِّنتي.","74":"P*3f. يُسقط الغوتي بيدقًا يهاجم الحصان في 3g.","75":"B*6f. يُسقط السِّنتي فيله. عبر القطر يهاجم الرخ في 8d. يدافع ويهاجم قطعة كبيرة في آن واحد: عصفوران بحجر واحد.","76":"R-8a. يُنقذ الغوتي رخه. بنقلة فيل واحدة أعاد السِّنتي رخ الغوتي إلى الأسفل.","77":"Nx4e. يقفز الحصان ويأسر البيدق في 4e. بعدها يريد القفز إلى 3c أو 5c.","78":"G*4f. يُسقط الغوتي ذهبًا يضغط على الحصان من الخلف.","79":"P-3c+. يتقدم بيدق 3d إلى 3c ويترقّى إلى توكين. دخلت قطعة للسِّنتي قرب ملك الغوتي.","80":"Nx3c. يأسر الغوتي التوكين بحصانه.","81":"Nx3c+. يأسر حصان السِّنتي في 4e ذلك الحصان ويترقّى. قطعةً بقطعة، يقلّل السِّنتي مدافعي ملك الغوتي.","82":"Bx3c. يستردّ الغوتي الحصان المترقّي بالفيل.","83":"S-5g. يرفع السِّنتي الفضة إلى 5g لتصطدم بذهب الغوتي في 4f وتطرد الذهب الذي اقترب.","85":"Gx5g. تبادل الطرفان الفضة والذهب. نظّف السِّنتي معسكره من قطعة الغوتي التي دخلته.","86":"P-7e. يدفع الغوتي بيدق العمود 7 مستهدفًا رأس ملك السِّنتي.","87":"N*4e. يُسقط السِّنتي حصانًا مرة أخرى. هذا الحصان يهاجم الفيل في 3c.","88":"B-2d. يُبعد الغوتي فيله إلى 2d.","89":"P*3c. يُسقط السِّنتي بيدقًا ليدقّ إسفينًا قرب ملك الغوتي.","90":"G-2b. يسحب الغوتي الذهب للدفاع.","91":"P-5d. يدفع السِّنتي بيدق العمود 5 أكثر ويستدرج فضة الغوتي إلى 5d.","92":"Sx5d. يأسر الغوتي البيدق بالفضة. لكن بذلك يفرغ المربع 4c، وهذا يرتبط بنقلات السِّنتي التالية.","93":"Rx2d. هذه نقطة التحول. يأسر السِّنتي فيل الغوتي بالرخ. حتى لو خسر الرخ، يقدّر أنه يستطيع في الأثناء الانقضاض على ملك الغوتي.","94":"Px2d. يأسر الغوتي الرخ ببيدق. أعطى السِّنتي رخه، لكنه كسب فيلًا، قطعة هجومية، في يده.","95":"B*3b، كِش. يُسقط السِّنتي الفيل. بعد Rx2d هذه هي البداية الحقيقية لهجوم السِّنتي.","96":"K-5a. يهرب ملك الغوتي إلى 5a.","97":"Bx5d+. يأسر الفيل الفضة في 5d ويترقّى إلى حصان التنين. ولأن 4c كان فارغًا، وصل الفيل مباشرة على القطر. المربع الذي أفرغته Sx5d في النقلة 92 أثمر هنا.","98":"Px5d. يأسر الغوتي حصان التنين ببيدق. أعطى السِّنتي كل قطعه الكبيرة، لكن فضة الغوتي المدافعة ذهبت أيضًا.","99":"P*5c. يُسقط السِّنتي بيدقًا أمام ملك الغوتي مباشرة كموطئ قدم. بعدها يريد الترقية في 5b.","100":"R*4h. يردّ الغوتي ويُسقط الرخ الذي كسبه في معسكر السِّنتي. تصير المباراة سباقًا: أيّ هجوم أسرع؟","101":"S-5h. يسحب السِّنتي الفضة للدفاع ويمنع الرخ من الانزلاق جانبيًا نحو الملك.","102":"B*5f، كِش. يُسقط الغوتي فيلًا. من 5f يصل قطريًا عبر 6g إلى الملك في 7h.","103":"K-8h. ينزل السِّنتي بملكه خطوة خارج خط الفيل. بهذه النقلة الدفاعية يضمن ألا يخسر السباق.","104":"Bx4e. يأسر فيل الغوتي الحصان.","105":"Px5b+. يترقّى البيدق إلى توكين ويأسر ذهب الغوتي. صارت قطعة للسِّنتي بجوار ملك الغوتي مباشرة.","106":"Kx5b. يأسر الغوتي التوكين بالملك.","107":"P*5c، كِش. يمكن إسقاط البيادق مرارًا، فيستطيع السِّنتي مواصلة الكِش هكذا (لكن لا يجوز وجود بيدقين غير مترقّيين لك في العمود نفسه).","108":"K-6b. يهرب ملك الغوتي إلى 6b.","109":"S*6d. يُسقط السِّنتي فضة ليغلق طرق هروب الملك.","110":"S*7d. يُسقط الغوتي فضة أيضًا للدفاع.","111":"P-5b+. يصنع السِّنتي توكين ويهاجم الملك من الخلف أيضًا.","112":"K-7b. يذهب ملك الغوتي إلى 7b. شيئًا فشيئًا يُدفع نحو الحافة.","113":"Sx7c+. تأسر الفضة الحصان في 7c وتترقّى. ذهب مدافع آخر للغوتي.","114":"Kx7c. يأسر الغوتي الفضة المترقّية بالملك.","115":"G*6d، كِش. من هنا يستعمل السِّنتي القطع التي في يده لاصطياد ملك الغوتي.","116":"K-8c. يذهب ملك الغوتي إلى 8c.","117":"Gx7d، كِش. يأسر الذهب الفضة في 7d مع كِش، وينزع مدافعي ملك الغوتي.","118":"Kx7d. يأسر الغوتي الذهب بالملك. سُحب الملك نحو وسط الرقعة.","119":"Sx7e، كِش. تأسر فضة 8f بيدقًا مع كِش. الفضة التي صعدت للدفاع في النقلة 69 تنضمّ إلى الهجوم في النهاية.","120":"K-6c. يهرب ملك الغوتي إلى 6c.","121":"S-6d، كِش. تنتقل فضة 7e إلى 6d مع كِش. ما زال في يد السِّنتي ذهب وفضة وحصان؛ وحين رأى سوكي أن الملك لا يستطيع الإفلات، استسلم هنا. يفوز سوئي في 121 نقلة. بعد قتال الوسط بنى السِّنتي أولًا قلعة متينة، ثم وسّع الهجوم إلى الأعمدة 2 و3 و4، وأخيرًا ضحّى برخه لينقضّ على الملك. إنها تحفة بين ميجينين تُظهر شوغي سوئي: «الدفاع أولًا ثم الهجوم»."}},"soho1856":{"t":"سوهو القدّيس وفيله البعيد النظر","w":"أمانو سوهو","b":"إيتو سوإين (الثامن)","ev":"أوشيرو شوغي (المباراة السنوية في قلعة إيدو)","d":"1856","pl":"اليابان (إيدو)","lead":"لعب أمانو سوهو، الملقّب بـ«قدّيس الشوغي»، مباراة القلعة هذه ضد إيتو سوإين الثامن الذي صار لاحقًا ميجين، وكانت آخر مباراة قلعة لسوهو. في النقلة 33 أسقط فيلًا في زاوية معسكره هو، B*1h، وهي نقلة يذكرها تاريخ الشوغي ضربةَ معلّم. يفوز سوهو في 111 نقلة.","c":{"0":"أنا Musowl. لعب أمانو سوهو في أواخر عصر إيدو، وكان قويًا جدًا حتى سُمّي «دان ثالث عشر حقيقي» و«قدّيس الشوغي». لكنه لم يولد في أحد بيوت الشوغي، فلم يستطع أن يصير ميجين أبدًا. أما الغوتي إيتو سوإين الثامن فكان أصغر من سوهو في المدرسة نفسها، وصار لاحقًا ميجين. كانت مباراة القلعة هذه عام 1856 آخر مباراة قلعة لعبها سوهو. يُقال إن سوهو كان أستاذًا في استعمال الفيل، فانتبه إلى الأفيال في هذه المباراة.","1":"P-7f. تفتح النقلة الأولى قطر الفيل. سيكون فيل سوهو نجم هذه المباراة.","3":"P-2f. يدفع السِّنتي البيدق الذي أمام الرخ. كان سوهو يحب الافتتاحات السريعة، فيدفع بيدق الرخ مبكرًا ويحرّك قطعه.","4":"P-5d. يدفع الغوتي بيدق الوسط. تظهر خطة: سيذهب الرخ إلى العمود 5 رخًا أوسط.","7":"S-4h. يرفع السِّنتي الفضة اليمنى استعدادًا للهجوم والدفاع.","11":"P-2e. يدفع السِّنتي بيدق الرخ أكثر. ينوي بعدها الاصطدام في 2d.","12":"S-6d. يقدّم الغوتي فضة. الفكرة دفعها نحو 5e والهجوم في الوسط.","13":"P-2d. يصدم السِّنتي ببيدقه بيدق الغوتي ليتبادل بيدق الرخ. إنها طريقة طبيعية لبدء القتال، وما زالت شائعة اليوم.","15":"Rx2d. يأسر الرخ البيدق. يكسب السِّنتي بيدقًا في يده ويتقدم الرخ. تبادل بيدق الرخ يعطيك بيدقًا إضافيًا في اليد ويجعل الرخ أسهل استعمالًا.","16":"R-5b. ينقل الغوتي رخه إلى العمود 5. بالرخ الأوسط ينوي الرد من الوسط.","17":"K-6i. ينقل السِّنتي ملكه إلى اليسار، بعيدًا عن الوسط حيث سيهاجم الرخ الأوسط.","19":"R-2h. يعود الرخ إلى بيته. بعد كسب بيدق، يسحبه السِّنتي بهدوء.","20":"P*2c. يُسقط الغوتي بيدقًا ليسدّ الثغرة في العمود 2.","21":"Bx2b+. هنا يتبادل السِّنتي الفيلين. بعد التبادل يكون لكل طرف فيل في يده يستطيع إسقاطه في أي مكان. ومن الآن يُظهر سوهو براعته في اختيار مكان إسقاط فيله.","22":"Sx2b. يستردّ الغوتي بالفضة. صار لكل طرف فيل في يده.","24":"P-5e. يصدم الغوتي ببيدق الوسط بيدق السِّنتي. إنه هجوم نموذجي للرخ الأوسط.","26":"Sx5e. تصل فضة الغوتي حتى 5e. قطع الغوتي تزداد قوة في الوسط.","27":"P*5d. يُسقط السِّنتي بيدقًا داخل معسكر الغوتي. البيدق في 5d يسدّ ما أمام رخ الغوتي ويعرقل قطعه.","29":"B*5c. يُسقط السِّنتي فيله داخل معسكر الغوتي. الفكرة أن يعيث فسادًا داخل موقع الغوتي.","30":"B*4d. يُسقط الغوتي فيله أيضًا ويصدم به فيل السِّنتي. إنها نقلة دفاعية للتخلص من فيل السِّنتي.","31":"Bx4d+. يأسر فيل السِّنتي فيل الغوتي ويترقّى.","32":"Sx4d. يستردّ الغوتي حصان التنين بالفضة. تبادل الطرفان الفيلين مرة أخرى، وعاد في يد السِّنتي فيل.","33":"B*1h. هذه هي اللحظة الشهيرة. يُسقط سوهو فيله في زاوية معسكره، في 1h. عبر قطره ينظر عبر الرقعة كلها حتى معسكر الغوتي. الآن يسند البيدق في 5d من الخلف، ولاحقًا حين ينفتح القطر سيقوم بعمل كبير: إنه «الفيل البعيد النظر». يُعدّ من ضربات المعلّمين في تاريخ الشوغي، وإن كان بعض الميجين اللاحقين يرون أنه ربما كان مخرجًا ذكيًا من موقف صعب.","34":"G-4b. يقرّب الغوتي ذهبًا ليثبّت ما حول الملك.","35":"S-5g. يرفع السِّنتي فضة استعدادًا لقتال الوسط.","37":"S-5f. تتقدم الفضة أكثر وتستهدف مربعي الوسط 5e و4e.","39":"R-5h. ينقل السِّنتي رخه إلى الوسط. السِّنتي أيضًا يجمع قوته في العمود 5 بشكل الرخ الأوسط.","41":"P-6f. يدفع السِّنتي بيدق العمود 6 ليفتح الطريق لفضته وفيله.","43":"K-7i. يدخل الملك أعمق إلى اليسار. حتى سوهو يرتّب دفاع الملك قبل الهجوم.","45":"G-5i. يقرّب السِّنتي ذهبًا من الملك ليقوّي الدفاع.","46":"P-8e. يدفع الغوتي بيدق العمود 8 ويستعدّ للهجوم من قرب ملك السِّنتي.","47":"B-2g. يصعد فيل 1h مربعًا واحدًا. بتحريك خطه قليلًا صار يستهدف 4e و3f.","49":"S-4e. تتقدم الفضة إلى 4e وتضغط على معسكر الغوتي. الفيل في 2g يسندها من الخلف.","50":"P*5e. يُسقط الغوتي بيدقًا ليغلق الوسط.","52":"P-8f. يبدأ الغوتي قتالًا في العمود 8 ويصدم البيدق القريب من ملك السِّنتي.","54":"P-7e. يصدم الغوتي أيضًا ببيدق العمود 7. يحاول كسر عدة بيادق أمام ملك السِّنتي.","56":"Sx4e. تأسر فضة الغوتي فضة السِّنتي في 4e.","57":"Bx4e. يستردّ فيل 2g الفضة في 4e. قطر الفيل كان مفيدًا هنا.","58":"S-4d. يرفع الغوتي فضة ليطارد الفيل في 4e.","59":"B-1h. يعود الفيل مرة أخرى إلى الزاوية في 1h. حين طاردته الفضة رجع إلى مكانه الذي يرى منه بعيدًا. انظر كيف سيعمل هذا الفيل في النهاية.","60":"S*5f. يُسقط الغوتي فضة ويهاجم في الوسط.","61":"Sx5f. يأسر السِّنتي بفضته.","62":"Px5f. يستردّ الغوتي ببيدق يصل إلى 5f.","63":"Rx5f. يأسر السِّنتي البيدق بالرخ. الرخ يعمل في الوسط.","64":"S*5e. يُسقط الغوتي فضة أخرى ليطارد رخ السِّنتي.","65":"R-5h. يعود الرخ إلى مكانه.","66":"Sx6f. تأسر فضة الغوتي البيدق في 6f وتقترب من ملك السِّنتي. يستمر هجوم الغوتي.","67":"P*6g. يُسقط السِّنتي بيدقًا حتى لا تدخل الفضة أكثر.","68":"P*7g. يُسقط الغوتي بيدقًا في 7g قرب ملك السِّنتي. يريد تحريك قطع السِّنتي وصنع ثغرة.","69":"Nx7g. يأسر السِّنتي البيدق بالحصان. لاحقًا سيقفز هذا الحصان إلى 6e ليهاجم.","70":"Sx7e. تأسر فضة الغوتي البيدق في 7e وتقترب من رأس ملك السِّنتي.","71":"G-6h. يقرّب السِّنتي ذهبًا ليحمي الملك.","72":"P*7f. يُسقط الغوتي بيدقًا آخر يستهدف الحصان. يصير هجوم الغوتي حادًا.","73":"N-6e. هنا يردّ السِّنتي. يقفز الحصان إلى 6e ويستهدف 5c في معسكر الغوتي.","74":"S-6d. يسحب الغوتي الفضة ليستهدف الحصان في 6e.","75":"S*5c. يُسقط السِّنتي فضة في عمق معسكر الغوتي. يسندها البيدق في 5d والحصان في 6e. البيدق الذي أسقطه السِّنتي في 5d منذ زمن طويل صار مفيدًا هنا.","76":"Gx5c. يأسر الغوتي الفضة بالذهب.","77":"Px5c+. يأسر بيدق 5d الذهب ويترقّى إلى توكين.","78":"Sx5c. يأسر الغوتي التوكين بالفضة.","79":"Nx5c+. يأسر حصان 6e تلك الفضة ويترقّى. يستمر الأسر، ويفرغ معسكر الغوتي أكثر فأكثر.","80":"Sx5c. يأسر الغوتي الحصان المترقّي بالفضة. لكن بيدق السِّنتي في 5d لم يعد موجودًا، فصار قطر فيل 1h مفتوحًا حتى 6c.","81":"Bx6c+. أخيرًا يتحرك فيل 1h. يندفع على القطر دفعة واحدة، يأسر البيدق في 6c ويصير حصان تنين. «الفيل البعيد النظر» الذي أُسقط في النقلة 33 يؤدي هنا عمله الكبير بعد 48 نقلة. إنها نقلة فيل حقيقية تجري من طرف الرقعة إلى طرفها الآخر.","82":"S*7g. يُسقط الغوتي فضة ليضغط على ملك السِّنتي. الغوتي أيضًا يواصل الهجوم.","83":"P*2d. يُسقط السِّنتي بيدقًا في العمود 2 ليهزّ ما حول ملك الغوتي.","84":"Px2d. يأسره الغوتي ببيدق.","85":"P*2e. يُسقط السِّنتي بيدقًا آخر. يستهدف بيدق الغوتي في 2d ويحاول فتح العمود 2.","86":"B*3c. يُسقط الغوتي فيلًا ليقوّي دفاعه.","87":"P*5e. يُسقط السِّنتي بيدقًا ليكبح حركة فضة الغوتي وفيله.","88":"Sx7h+. تأسر فضة الغوتي ذهب السِّنتي وتترقّى.","89":"Gx7h. يستردّ السِّنتي بالذهب.","90":"G*7g. يُسقط الغوتي ذهبًا يضغط على ملك السِّنتي. القتال قرب ملك السِّنتي شرس أيضًا.","91":"S*4e. يُسقط السِّنتي فضة. هذه الفضة تستهدف 3d قرب ملك الغوتي.","92":"R-6a. ينقل الغوتي رخه إلى العمود 6 ليهاجم حصان التنين لدى السِّنتي.","93":"+B-7d. يبتعد حصان التنين إلى 7d. إنها قطعة قوية: تنفع في معسكرها وفي معسكر الخصم.","94":"Px2e. يأسر بيدق الغوتي البيدق في 2e.","95":"Sx3d. تأسر الفضة البيدق في 3d. فضة السِّنتي الآن أمام ملك الغوتي مباشرة.","96":"B-2d. ينقل الغوتي فيله إلى 2d استعدادًا لهجوم السِّنتي.","97":"S*4f. يُسقط السِّنتي فضة أخرى. تقطع قطر الفيل في 2d وتحدّ مما يستطيع فعله.","98":"G*3c. يُسقط الغوتي ذهبًا للدفاع.","99":"Sx3c+. تأسر فضة 3d الذهب وتترقّى.","100":"Kx3c. يأسر الغوتي الفضة المترقّية بالملك. خرج ملك الغوتي إلى 3c حيث المدافعون قليلون.","101":"S*3e. يُسقط السِّنتي فضة أخرى. تهاجم الفيل في 2d وتغلق أيضًا أحد طرق هروب الملك.","102":"N*8g، كِش. يُسقط الغوتي حصانًا مع كِش. إنها المقاومة الأخيرة.","103":"Gx8g. يأسر السِّنتي الحصان بالذهب.","104":"Gx8g. يستردّ الغوتي بالذهب. لكن ملك السِّنتي لم يُمسك بعد.","105":"Sx2d، كِش. تأسر الفضة الفيل مع كِش. من هنا يطارد السِّنتي ملك الغوتي دفعة واحدة.","106":"Kx2d. يأسر الغوتي الفضة بالملك.","107":"S-3e، كِش. تنتقل فضة 4f إلى 3e مع كِش وتسحب ملك الغوتي خارج معسكره.","108":"Kx3e. يأسر ملك الغوتي الفضة ويخرج إلى 3e. الملك الذي يخرج إلى الوسط بلا مدافعين في خطر كبير.","109":"B*4f، كِش. الفيل مرة أخرى حتى النهاية. يُسقط السِّنتي الفيل من يده مع كِش. في مباراة سوهو كانت الأفيال نجومًا من البداية إلى النهاية.","110":"K-4d. يهرب ملك الغوتي إلى 4d.","111":"G*3d، كِش. حين رأى سوإين أن الملك لم يعد يستطيع الإفلات، استسلم هنا. يفوز سوهو في 111 نقلة. أدّت B*1h في النقلة 33 عملًا كبيرًا بعد 48 نقلة عبر Bx6c+، وحُسمت المباراة أيضًا بكِش من فيل. إنها تحفة تُظهر كيف كان سوهو يضع القطعة وهو ينظر بعيدًا إلى المستقبل."}}};
